        (228, 'SME 0017 - Cadastro de Documentos', '<div><ul style="color:rgb(34, 34, 34);font-family:Arial, Helvetica, sans-serif;font-size:small;"><li style="margin-left:15px;"><i><a href="https://docs.google.com/document/d/16Y7QL_2D_ELO-O6khXU5WpneMvPj-z4z/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0017</a><span>&nbsp;</span>- Cadastro de Documentos</i> </li> </ul><b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">História de usuário: Cadastro de Documentos</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO) e Empresa Cliente</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos documentos no sistema,</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa incluir esses documentos nas condições e critérios preestabelecidos pela empresa cliente.</span> </p></b><br><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7576', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', null, null, 5, 3, '2026-03-05 22:46:16.053', '2026-03-05 22:46:26', 129, null),
        (229, 'SME 0018 - Grupo de Documentos', '<div><i><a href="https://docs.google.com/document/d/1GC0J9-ALpyHsmYUll3jLNJMBC-63YJ2b/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0018</a><span>&nbsp;</span>- Grupo de Documentos</i><br> </div><div><i><br></i> </div><div><i><b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">História de usuário: Cadastro de Grupo Documentos</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">Como um usuário do tipo SESI (DN, DR e UO) e Empresa Cliente</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">Eu quero cadastrar grupo de documentos no sistema,</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">Para que eu possa incluir esse grupos documentos nas condições e critérios preestabelecidos pela empresa cliente.</span> </p></b><br><br></i> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7577', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'User Story', null, null, 6, 3, '2026-03-05 22:46:16.053', '2026-03-05 22:46:26', 129, null),
        (230, 'SME 0020 - Terceiro - Evolução Cadastro do Terceiro via portal (auto cadastro)- Estrangeiro e Pessoa Física', '<div><ul style="color:rgb(34, 34, 34);font-family:Arial, Helvetica, sans-serif;font-size:small;"><li style="margin-left:15px;"><i><a href="https://docs.google.com/document/d/1FUqdZ9eAsjwle5QiyZsjpMTJDmzmgkXV/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0020</a><span>&nbsp;</span>- Terceiro - Evolução Cadastro do Terceiro via portal (auto cadastro)- Estrangeiro e Pessoa Física</i> </li> </ul><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Descrição da evolução:</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Inicialmente a tela previa somente o cadastro de terceiros sendo pessoas jurídicas brasileiras.</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><br></span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">A evolução de tela aqui apresentada, possibilita que terceiros, tanto pessoa física quanto jurídica, e de nacionalidades tanto brasileira quanto estrangeira, realizem seu auto cadastro no SEIF.</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><br><br></span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Cadastrar Trabalhador - Estrangeiro</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo Terceiro,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero realizar auto cadastro via portal podendo ser pessoas físicas ou jurídicas, de nacionalidades brasileiras ou estrangeiras;</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa gerenciar minhas informações e contratações dentro do SEIF</span> </p><br></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7578', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', null, null, 5, 3, '2026-03-05 22:46:16.054', '2026-03-05 22:46:26', 129, null),
        (231, 'SME 0021 - Ajuste na Importação do Trabalhador', '<div><ul style="color:rgb(34, 34, 34);font-family:Arial, Helvetica, sans-serif;font-size:small;"><li style="margin-left:15px;"><i><a href="https://docs.google.com/document/d/1ROzSeGRt87HqAQbc7oZ-BGcmjy0IZL9l/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0021</a><span>&nbsp;</span>- Ajuste na Importação do Trabalhador</i> </li> </ul><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Importar Trabalhadores estrangeiros</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO) e Cliente,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero importar novos trabalhadores em massa (contemplando trabalhadores estrangeiros),</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu não possa gerenciar suas informações pessoais e contratações.</span> </p></b><br><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7579', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', 'FABIANO ANTONIO PANCHENIAK FILHO', 'fabiano.filho@sc.senai.br', 5, 3, '2026-03-05 22:46:16.054', '2026-03-05 22:46:26', 129, null),
        (232, 'SME 0023 - Evolução da Tela Cadastro de Terceiro - Estrangeiro', '<div><ul style="color:rgb(34, 34, 34);font-family:Arial, Helvetica, sans-serif;font-size:small;"><li style="margin-left:15px;"><i><a href="https://docs.google.com/document/d/1oYDaWKEE52WyNEL7BdyR738DkKv1DTMV/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0023</a><span>&nbsp;</span>- Evolução da Tela Cadastro de Terceiro - Estrangeiro</i> </li> </ul><b style="font-weight:normal;"><h3 dir=ltr style="text-align:justify;margin-top:14pt;margin-bottom:4pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Objetivo da Alteração:</span> </h3><h3 dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Descrição da Evolução:</span><span style="font-size:11pt;font-family:Calibri,sans-serif;color:#000000;font-weight:400;"> </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">A interface de cadastro deve ser evoluída para incluir uma nova funcionalidade que permita o cadastro de Terceiros sendo </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">pessoas físicas e jurídicas, (brasileiras ou estrangeiras)</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">, permitindo a utilização de outros tipos de documentos para identificação das entidades.</span> </h3><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Cadastrar Trabalhador - Estrangeiro</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI e Cliente,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos Terceiros, que podem ser pessoas físicas ou jurídicas (brasileiros ou estrangeiros),</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa gerenciar suas informações pessoais e contratações.</span> </p><br></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7580', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', null, null, 5, 3, '2026-03-05 22:46:16.055', '2026-03-05 22:46:26', 129, null),
        (233, 'SME 0024 - Evolução de tela - Contrato SESI X Cliente (Edição)', '<div><i><a href="https://docs.google.com/document/d/1EU6vNwyUvqqadunfY7A-8pLU36BWV6to/edit" target=_blank style="color:rgb(17, 85, 204);">SME 0024</a><span>&nbsp;</span>- Evolução de tela - Contrato SESI X Cliente (Edição)</i><br> </div><div><i><br></i> </div><div><i><b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;font-style:normal;">Como &lt;tipo de perfil/usuário/acesso&gt;, preciso/gostaria de &lt;necessidade&gt;, para &lt;objetivo&gt;</span> </p><br><br><br><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;font-style:normal;">História de usuário: Evolução de tela - Contrato SESI X Cliente (aditivo, edição)</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;font-style:normal;">Como </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">um usuário do tipo SESI,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;font-style:normal;">Eu quero</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;">&nbsp; aditivar e editar um Contrato com Clientes/ Empresas,</span> </p><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;font-style:normal;">Para poder</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;font-style:normal;"> incluir ou editar itens do contrato com o Clientes/ Empresa.</span></b><br></i> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '7581', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', null, null, 5, 3, '2026-03-05 22:46:16.055', '2026-03-05 22:46:26', 129, null),
