        (242, 'SME 0024 - Evolução de tela - Contrato SESI X Cliente (Edição e Visualização) - Back-end', null, null, null, 'completed', 'high', 'task', 'azure_devops', '7664', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 5, 3, '2026-03-05 22:46:16.060', '2026-03-05 22:46:26', 243, null),
        (243, 'SME 0017 - Cadastro de Documentos', '<div><b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">História de usuário: Cadastro de Documentos</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO) e Empresa Cliente</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos documentos no sistema,</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa incluir esses documentos nas condições e critérios preestabelecidos pela empresa cliente.</span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Requisitos / Critérios de Aceite:</span> </p><ul style="margin-top:0;margin-bottom:0;"><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:0pt;"><span>Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp; UOs, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span>Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:12pt;"><span>Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li> </ul></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8104', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 4', null, null, 'User Story', null, null, 5, 3, '2026-03-05 22:46:16.061', '2026-03-05 22:46:26', 129, null),
        (244, 'SME 0011 - Contrato Cliente x Terceiro - Visão Terceiro', '<div><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Contrato Cliente X Terceiro</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Como </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">um usuário do tipo Terceiro,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Eu quero</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> criar um Contrato com Clientes/ Empresas,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Para poder</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> prestar diversos serviços para os Clientes/ Empresa.</span> </p><br></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8105', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'User Story', null, null, 6, 3, '2026-03-05 22:46:16.062', '2026-03-05 22:46:26', 129, null),
        (245, 'SME 0019 - Evolução de tela - Ver trabalhadores - Dados Profissionais', '<div><b style=""><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:&quot;Arial Narrow&quot;, sans-serif;color:rgb(0, 0, 0);">História de usuário: Ver trabalhadores - Dados Profissionais<br><br></span> </p><p dir=ltr style="font-weight:normal;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO), Empresa Cliente e Terceiros</span> </p><p dir=ltr style="font-weight:normal;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero ver o cadastro e histórico do trabalhadores no sistema,</span> </p><p dir=ltr style="font-weight:normal;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa acompanhar e atualizar suas informações conforme os contratos.</span> </p></b><br><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8107', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'User Story', null, null, 6, 3, '2026-03-05 22:46:16.062', '2026-03-05 22:46:26', 129, null),
        (246, 'SME 0025 - Contrato Subcontratado x Terceiro', '<div><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Contrato Subcontratado x Terceiro</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><br></span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Como </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">um usuário do tipo Terceiro,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Eu quero</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> indicar um contrato com subcontratados,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Para poder</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> prestar diversos serviços para os Clientes/ Empresa.</span> </p></b><br><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8108', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 6', null, null, 'User Story', null, null, 7, 3, '2026-03-05 22:46:16.063', '2026-03-05 22:46:26', 129, null),
        (247, 'SME 0028 - Contrato Cliente X Terceiro - Visão Cliente', '<div><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Contrato Cliente X Terceiro</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><br></span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Como </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">um usuário do tipo Cliente e Terceiro,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Eu quero</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> indicar um Contrato com Clientes/ Empresas,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Para poder</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> prestar diversos serviços para os Clientes/ Empresa.</span> </p></b><br><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8109', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'User Story', null, null, 6, 3, '2026-03-05 22:46:16.064', '2026-03-05 22:46:26', 129, null),
