        (273, 'Contatos Front-end', '<div><span style="font-size:10pt;font-family:Montserrat,Arial;font-weight:bold;text-align:center;"><span>RF.4.1.5.05 - CADASTRAR CONTATOS<br>- </span><span style="font-weight:normal;">Usar como base tela de contatos de &quot;Contrato SESI x Cliente&quot;</span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '8156', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'Task', 'VINICIUS GABRIEL MARTINS DA SILVA', 'vinicius.gabriel@sc.senai.br', 6, 3, '2026-03-05 22:46:16.360', '2026-03-05 22:46:26', 244, null),
        (274, 'Dados gerais Back-end', '<div><span style="font-size:10pt;font-family:Montserrat,Arial;font-weight:bold;text-align:center;"><span>Aba: Geral:Dados gerais<br></span><span style="font-weight:normal;">- Endpoint para validar existencia de contrato.</span><span><br></span><span style="font-weight:normal;"> - Endpoint para buscar contrato.</span><span><br></span><span style="font-weight:normal;">- Endpoint de buscar empresas.<br>- Endpoint de buscar os estabelecimento e unidades da empresa.<br></span><span>(Validar se já não existe esses endpoints)</span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '8159', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 6, 3, '2026-03-05 22:46:16.360', '2026-03-05 22:46:26', 244, null),
        (275, 'Informações de contratos Back-end', '<div><span style="font-size:10pt;font-family:Montserrat,Arial;font-weight:bold;text-align:center;"><span>Aba: Informações de contratos<br></span><span style="font-weight:normal;">- Endpoint para salvar o contrato em estado de &quot;em elaboração&quot;.</span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '8164', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 6, 3, '2026-03-05 22:46:16.361', '2026-03-05 22:46:26', 244, null),
        (276, 'Trabalhadores Back-end', '<div><span style="font-size:10pt;font-family:Montserrat,Arial;font-weight:normal;text-align:center;"><span style="font-weight:bold;">Aba: Trabalhadores</span><span><br>- Endpoint de solicitação para aprovação de contrato.<br>- Endpoint para buscar os contadores por cargo.<br>- Endpoint de cadastrar trabalhador<br>- Endpoint de cadastrar e vincular trabalhador no contrato.<br>- Endpoint Desvincular trabalhador no contrato.&nbsp;</span><span><br>- Endpoint de inativar trabalhador</span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '8166', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 6, 3, '2026-03-05 22:46:16.361', '2026-03-05 22:46:26', 244, null),
        (277, 'Contatos Back-end', '<div><span style="font-size:10pt;font-family:Montserrat,Arial;font-weight:bold;text-align:center;"><span>RF.4.1.5.05 - CADASTRAR CONTATOS<br></span><span style="font-weight:normal;">Criar endpoint padrões de contatos como já existe no sistema. Exemplo.: Contrato de Sesi x Cliente, Empresa.</span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '8167', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 5', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 6, 3, '2026-03-05 22:46:16.362', '2026-03-05 22:46:26', 244, null),
        (278, 'SME 0032 - Integração com o Nukleo', '<div><span style="font-size:9pt;font-family:Montserrat,Arial;font-weight:normal;"><span><a target=_blank href="https://docs.google.com/document/d/1g2_2gILfVrdmzSbf3WOpn1N_45Vux_j5/edit"><span>SME 0032 - Integração com o Nukleo.docx</span></a></span></span><br> </div><div><span style="font-size:9pt;font-family:Montserrat,Arial;font-weight:normal;"><br></span> </div><div><span style="font-size:9pt;font-family:Montserrat,Arial;font-weight:normal;"><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História do Usuário: Consulta CNPJ via API Nukleo</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><br></span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Como </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">usuário do sistema SESI, Cliente ou Terceiro </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><br></span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Eu preciso</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> realizar um cadastro de Empresa, Terceiro ou Subcontratado no SEIF, consultado seu CNPJ via API Nulkleo </span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><br></span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">para</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"> validar os dados da entidade e cadastra-los corretamente no SEIF.</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Requisitos / Critérios de Aceite:</span> </p><ul style="margin-top:0;margin-bottom:0;"><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:0pt;"><span>Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp; UOs, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span>Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:12pt;"><span>Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li> </ul></b><br></span> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8476', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 6', null, null, 'User Story', 'FABIANO ANTONIO PANCHENIAK FILHO', 'fabiano.filho@sc.senai.br', 7, 3, '2026-03-05 22:46:16.366', '2026-03-05 22:46:26', 129, null),
        (279, 'SEIF Fase 3', null, null, null, 'completed', 'high', 'task', 'azure_devops', '8543', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 1', null, null, 'Epic', null, null, 2, 3, '2026-03-05 22:46:16.370', '2026-03-05 22:46:26', 321, null),
        (280, 'SME 0035 - Evolução de Tela - Criação formulário - Vinculos', '<div><span><b><a target=_blank href="https://drive.google.com/file/d/1dnRppdJYoYRKA-MB64_29WBGWMR_44t1/view" rel="noopener noreferrer" style="text-decoration:underline;font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;text-align:left;background-color:rgb(34, 37, 41);"><span style="color:rgb(0, 0, 0);background-color:rgb(255, 255, 128);">SME 0035 - Evolução de Tela - Criação formulário - Vinculos</span></a><br><br><br>História do Usuário: Criação e edição de Formulário - Vínculos de documentos<br></b></span><div>Como usuário do sistema SESI,<br> </div><div>Eu preciso criar e customizar formulários, permitindo a inserção de perguntas com flexibilidade, vinculando as<br> </div><div>respostas de itens a documentos e respostas de perguntas a novas seções;<br> </div><div>para atender diferentes tipos de empresas e requisitos operacionais.<br><br><br><br> </div><div><b>Requisitos / Critérios de Aceite:<br></b> </div><div>● Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp;amp; UOs, de acordo com a regra de acesso<br> </div><div>por entidade e seus respectivos vínculos.<br> </div><div>● Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a<br> </div><div>regra de acesso por entidade e seus respectivos vínculos.<br> </div><div>● Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por<br> </div><div>entidade e seus respectivos vínculos.<br> </div><div>● Na criação do formulário, o sistema deve permitir o vínculo de perguntas, seções e respostas com<br> </div><span>documentos, para solicitações durante mobilizações.</span><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8683', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 7', null, null, 'User Story', null, null, 8, 3, '2026-03-05 22:46:16.370', '2026-03-05 22:46:26', 129, null),
        (281, 'SME 0014 - Critérios de Mobilização - Listagem, cabeçalho e documentos', '<div><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><a href="https://docs.google.com/document/d/1T238YHFfMacD6l2tWlEi6pAnGB8xaMDo/edit#heading=h.smx8r5qtegj1">SME 0014 - Critérios de Mobilização - Listagem, cabeçalho e documentos<br></a></span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><br></span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Tela de Critérios</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO),</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos critérios para Empresas Clientes no sistema,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa gerenciar critérios da Empresa Cliente, exigindo obrigatoriedade de documentos para mobilização e demais módulos do sistema.</span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Requisitos / Critérios de Aceite:</span> </p><ul style="margin-top:0;margin-bottom:0;"><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:0pt;"><span>Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp; UOs, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span>Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:12pt;"><span>Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li> </ul></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8684', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 7', null, null, 'User Story', null, null, 8, 3, '2026-03-05 22:46:16.371', '2026-03-05 22:46:26', 129, null),
        (282, 'SME 0029 - Criterios de Mobilização- Bloco criterios', '<b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-family:&quot;Arial Narrow&quot;, sans-serif;font-size:11pt;font-weight:700;"><a href="https://docs.google.com/document/d/1Pew_CQ8RkT7ocvxcNxs-_pjKfUfLghWh/edit">SME 0029 - Criterios de Mobilização- Bloco criterios<br></a></span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-family:&quot;Arial Narrow&quot;, sans-serif;font-size:11pt;font-weight:700;">História de usuário: Tela de Critérios</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO),</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos critérios para Empresas Clientes no sistema,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa gerenciar critérios da Empresa Cliente, exigindo obrigatoriedade de documentos para mobilização e demais módulos do sistema.</span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Requisitos / Critérios de Aceite:</span> </p><ul style="margin-top:0;margin-bottom:0;"><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:0pt;"><span>Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp; UOs, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span>Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:12pt;"><span>Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li> </ul></b><br><br>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8685', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 7', null, null, 'User Story', null, null, 8, 3, '2026-03-05 22:46:16.371', '2026-03-05 22:46:26', 129, null),
        (283, 'SME 0030 - Critérios de Mobilização- Bloco Formularios', '<div><b style="font-weight:normal;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;"><a href="https://docs.google.com/document/d/1llr-sW5uIf4a_tyuQ2Zr44WnO5V_xdpb/edit">SME 0030 - Critérios de Mobilização- Bloco Formularios<br></a></span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">História de usuário: Tela de Critérios</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Como um usuário do tipo SESI (DN, DR e UO),</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Eu quero cadastrar novos critérios para Empresas Clientes no sistema,</span> </p><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">Para que eu possa gerenciar critérios da Empresa Cliente, exigindo obrigatoriedade de documentos para mobilização e demais módulos do sistema.</span> </p><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:12pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:700;">Requisitos / Critérios de Aceite:</span> </p><ul style="margin-top:0;margin-bottom:0;"><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:12pt;margin-bottom:0pt;"><span>Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp; UOs, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:0pt;"><span>Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li><li dir=ltr style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><p dir=ltr style="text-align:justify;margin-top:0pt;margin-bottom:12pt;"><span>Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por entidade e seus respectivos vínculos.</span> </p> </li> </ul></b><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8686', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 7', null, null, 'User Story', null, null, 8, 3, '2026-03-05 22:46:16.372', '2026-03-05 22:46:26', 129, null),
        (284, 'SME 0036 - Criação formulário - Avaliação do formulario - Visão SESI', '<div><span><b><a href="https://drive.google.com/file/d/1zw_QHKnUY0LGk9s5yg8jCHCA8Pz28diZ/view">SME 0036 - Criação formulário - Avaliação do formulario - Visão SESI<br></a><br><br>História do Usuário: Avaliação de Formulário<br></b></span><div>Como usuário do sistema SESI,<br> </div><div>Eu preciso avaliar os formulários criados pelos clientes<br> </div><div>para identificar possíveis inconsistências no formulários criados, e orientar os clientes sobre a necessidade de<br> </div><div>adequações<br><b><br></b> </div><div><b>Requisitos / Critérios de Aceite:<br></b><br> </div><div>● Os usuários do tipo “DN” poderão visualizar tudo de DN, DRs &amp;amp; UOs, de acordo com a regra de acesso<br> </div><div>por entidade e seus respectivos vínculos.<br> </div><div>● Os usuários do tipo “DR”, poderão visualizar tudo do seu DR e suas UOs vinculadas, de acordo com a<br> </div><div>regra de acesso por entidade e seus respectivos vínculos.<br> </div><div>● Os usuários do tipo “UO”, poderão visualizar tudo da sua UO, de acordo com a regra de acesso por<br> </div><span>entidade e seus respectivos vínculos.</span><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '8687', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 3 2024\Sprint 8', null, null, 'User Story', null, null, 9, 3, '2026-03-05 22:46:16.372', '2026-03-05 22:46:26', 129, null),
