        (403, 'SME 1009 - (SME não fala da validação de e-mail que o sistema tem)', '<div>Para Análise, é preciso informar as validações existentes no campo de e-mail na SME. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12802', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.332', '2026-03-05 22:46:26', 442, null),
        (404, 'SME 1009 - 4.b Quando inserimos um cargo qu não está na lista permite sem este botão de “CADASTRAR NOVO CARGO”', '<div>Para análise, a SME menciona um campo cadastrar novo cargo, mas esse botão não está no protótipo e nem no projeto, ao digitar o cargo e salvar o usuário já é salvo no banco, ajustar a documentação. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/0cabd8a3-7106-430e-897d-1dfdc3b9e857?fileName=image.png" alt=Image> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12803', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'DIEGO ALVES DA LUZ', 'diego.l@sc.senai.br', 20, 3, '2026-03-05 22:46:17.333', '2026-03-05 22:46:26', 442, null),
        (405, 'Homologação DN - SME 1005', '<div>documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1JZjFTyV8i3jTiUUhZwIZU2_OSaLuStRs/edit">https://docs.google.com/document/d/1JZjFTyV8i3jTiUUhZwIZU2_OSaLuStRs/edit</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12806', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', 'JULIA STEPHANIE ANTONIO', 'julia.antonio@sc.senai.br', 20, 3, '2026-03-05 22:46:17.333', '2026-03-05 22:46:26', 443, null),
        (406, 'SME 1005 - O sistema deve permitir o SESI e não o terceiro, que foi a SME 1004', '<div>Ajsutar a sme para Sesi ao invés de terceiro nos 3 pontos abaixo </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/0317f6dc-bb2e-46d6-806f-277db65d7b28?fileName=image.png" alt=Image width=640 height=275 style="width:640px;"><br> </div><div><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/008efdec-e617-42c5-9db1-399aecd6bb3e?fileName=image.png" alt=Image><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/8e7a117e-da71-49e4-8d83-33d5b4115eac?fileName=image.png" alt=Image><br> </div><div><br> </div><div>ajustado a SME </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12810', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.334', '2026-03-05 22:46:26', 405, null),
        (407, 'Homologação DN - SME 1011', '<div>Documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1etqfJvlyyDOCe2MxniTDym8fIQDnaO2j/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true">https://docs.google.com/document/d/1etqfJvlyyDOCe2MxniTDym8fIQDnaO2j/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12811', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', 'JULIA STEPHANIE ANTONIO', 'julia.antonio@sc.senai.br', 20, 3, '2026-03-05 22:46:17.335', '2026-03-05 22:46:26', 443, null),
        (408, 'SME 1011 - Faltou a SME falar do ícone de ação ‘Ver mobilização”', '<div>Faltou mencionar na SME sobre esse botão, o homologador apontou isso em dois lugares no mesmo documento, não entendi se precisa incluir em mais de um lugar na SME. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/71afea55-f4b2-44a3-b28e-467b4a694b37?fileName=image.png" alt=Image><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/bdec70b9-95e3-4f01-a52e-3febdf35222f?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12812', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'DIEGO ALVES DA LUZ', 'diego.l@sc.senai.br', 20, 3, '2026-03-05 22:46:17.335', '2026-03-05 22:46:26', 407, null),
        (409, 'Homologação DN - SME 1007', '<div>Documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1Xl8yZOWon9CAgo1-GQQCHla0pYXVyBPf/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true">https://docs.google.com/document/d/1Xl8yZOWon9CAgo1-GQQCHla0pYXVyBPf/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12813', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', 'JULIA STEPHANIE ANTONIO', 'julia.antonio@sc.senai.br', 20, 3, '2026-03-05 22:46:17.336', '2026-03-05 22:46:26', 443, null),
