        (411, 'Homologação DN - SME 1002', '<div>Documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1cmo-vGhbJasspTS8bOMGPnQH2pqAG5X3/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true">https://docs.google.com/document/d/1cmo-vGhbJasspTS8bOMGPnQH2pqAG5X3/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12815', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', 'JULIA STEPHANIE ANTONIO', 'julia.antonio@sc.senai.br', 20, 3, '2026-03-05 22:46:17.336', '2026-03-05 22:46:26', 443, null),
        (412, 'SME 1002 - A SME não fala da busca de documentos já no sistema: ( se for melhoria de outra SME posterior, OK', '<div>Precisa incluir informações sobre esse campo na SME:&nbsp;<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/61d00830-c2dd-4697-83f3-b53792aed856?fileName=image.png" alt=Image> </div><div><br> </div><div>Inserido na documentação: </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/fc09ccb4-de55-431d-9597-9c290e943a91?fileName=image.png" alt=Image> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12819', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.337', '2026-03-05 22:46:26', 411, null),
        (413, 'SME 1002 - Problema API Nukleo', '<div>Aguardando solução por parte do fornecedor da API. </div><div><br> </div><div><br> </div><div>Retorno do nukleo, alterar caminho da api para homologação.<br><br><span>HOMOL<br></span><div>Login:<br> </div><div>https://hml-api.apps.ocp.sistemaindustria.com.br/api-autenticacao/oauth2/token?grant_type=client_credentials&amp;client_id=YXBpLWNucGo6Y2xpZW50X2NyZWRlbnRpYWxzOjAxLzA3LzIwMjQ%3D&amp;client_secret=MDEvMDcvMjAyNDpjbGllbnRfY3JlZGVudGlhbHM6YXBpLWNucGo%3D<br> </div><div>Url:<br> </div><span><a href="https://api-cnpj.hml.apps.sistemaindustria.com.br/api-cnpj/api/pessoa-juridica/" target=_blank rel="noopener noreferrer">https://api-cnpj.hml.apps.sistemaindustria.com.br/api-cnpj/api/pessoa-juridica/</a></span><br> </div><div><br> </div><div><a href="#" data-vss-mention="version:2.0,a24e0098-0d8b-606c-9527-c5cbe123f345">@FABIANO ANTONIO PANCHENIAK FILHO</a>&nbsp;favor ajustar para o <a href="#" data-vss-mention="version:2.0,253d4d9a-698c-646f-b6fc-850533928cab">@LUCAS VIANA RODRIGUES</a>&nbsp;efetuar o teste. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12822', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.337', '2026-03-05 22:46:26', 411, null),
        (414, 'SME 1002 - 1.j corrigir SME para veículos e não trabalhadores', '<div>Ajustar a SME para Veículos e não trabalhadores:&nbsp;<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/beeeed63-d803-4229-b302-0b1088233cc2?fileName=image.png" alt=Image> </div><div><br> </div><div>Corrigido. [Att. Juliana - 08/04/2025 </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12829', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.338', '2026-03-05 22:46:26', 411, null),
        (415, 'SME 1002 - 2.d: Observação que na SME onde diz que é ‘status’, na verdade é ‘mobilizado’', '<div>Ajustar a SME de acordo com as colunas do projeto </div><div><br> </div><div><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/dcecaa2f-21e2-4801-87bb-6a63eed39607?fileName=image.png" alt=Image><br> </div><div>ajustado sme e documento de requisito. </div><div><br> </div><div>[Att. Juliana - 08/04/2025] </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12830', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.338', '2026-03-05 22:46:26', 411, null),
        (416, 'SME 1002 - O sistema está como ‘data de cadastro’ e não como ‘enviado’ como aponta a SME.', '<div>1 - Tirar o item 4.a </div><div><br> </div><div>2 - Alterar de Enviado para Data de cadastro </div><div><br> </div><div>3 - o item 4 trocar veículos por máquinas e equipamentos </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/2d19b54b-5d53-4f49-9b23-8de05d52b4a3?fileName=image.png" alt=Image width=813 height=208 style="width:813px;height:208px;"><br> </div><div><br> </div><div>Ajustado a SME </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/131c5125-5bbb-4907-a138-3a844f899688?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12831', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.338', '2026-03-05 22:46:26', 411, null),
        (417, 'SME 1002 - 5.a. não tem opções já vai para o cadastro', '<div>Ajustar a SME de acordo com o projeto, hoje clicando no botão de cadastrar vai direto para o formulário de cadastro:&nbsp;<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1defae86-6ac6-481e-bfda-96bfa7b6c062?fileName=image.png" alt=Image> </div><div><br> </div><div>Ajustado a SME e doc de analise. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12833', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.339', '2026-03-05 22:46:26', 411, null),
        (418, 'SME1002 - Como filtra por ícone de ações?', '<div>Ajustar a SME nessa parte com o que realmente há no projeto:&nbsp; </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/82b02897-9056-4a93-bed8-5315ac485507?fileName=image.png" alt=Image><br> </div><div><br> </div><div>Ajustado na sme. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12834', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.339', '2026-03-05 22:46:26', 411, null),
        (419, 'SME 1002 - 4 grid: Faltou ‘mobilizado’ na SME', '<div>Faltou a coluna mobilizado:&nbsp;<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/bd0f9a2c-ff58-4112-baa9-9964e6774961?fileName=image.png" alt=Image> </div><div>ajustado na sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12835', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.340', '2026-03-05 22:46:26', 411, null),
        (420, 'SME 1002 - 7.O sistema permite por situação (e não por emissão) e por nome:', '<div>Ajustar a SME para Situação e não emissão:&nbsp; </div><div><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/6f9a2b82-c1d4-47e3-a88f-f252e4527249?fileName=image.png" alt=Image> </div><div><br> </div><div>ajustado a sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12836', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.340', '2026-03-05 22:46:26', 411, null),
        (421, 'SME 1002 - Como estamos na visão do terceiro, ao abrir a mobilização ele não seleciona terceiro.', '<div><b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:12pt;font-family:Arial,sans-serif;color:#000000;background-color:#00ffff;font-weight:400;">1.d. Este item da SME, fiquei com dúvida. Como estamos na visão do terceiro, ao abrir a mobilização ele não seleciona terceiro:</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;background-color:#00ffff;font-weight:400;">“Caso a Empresa cliente utilize o método de critério: Formulário para mobilização do terceiro, ao abrir a mobilização o sistema deve&nbsp; solicitar a seleção do terceiro, seleção do contrato e da UE, para carregar o formulário de mobilização;”</span> </p></b><br>Ajustar na SME, Excluir a parte selecionada: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/f0f5dcae-104a-49bd-988d-54c76cf01586?fileName=image.png" alt=Image> </div><div><br> </div><div>ajustado a sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12839', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.340', '2026-03-05 22:46:26', 411, null),
        (422, 'SME 1002 - Poderia explicar?', '<b style="font-weight:normal;"><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;background-color:#00ff00;font-weight:400;">Poderia explicar?</span> </p><p dir=ltr style="margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;background-color:#00ff00;font-weight:400;">Quando estamos em “Ver mobilizações”, como terceiro, selecionamos a empresa cliente, para acessar a mobilização e responder ao formulário e subir os doc do critério.</span> </p></b><br><div>Pelo que entendi, acredito que o homologador quer que informe isso acima em algum lugar na SME, mas deve ser confirmado com ele. </div><div><br> </div><div><br> </div><div>Avaliar com o homologador&nbsp; </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12840', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.341', '2026-03-05 22:46:26', 411, null),
        (423, 'SME 1002 - 8 não encontrei o campo ‘Informações complementares’, poderia indicar, se houver?', '<div>Ajustar na SME para ficar ao mesmo item que já está ajustado na SME 1003 da visão Sesi:&nbsp;&nbsp; </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/494008dd-ac11-4817-8033-b3a5bc902ad1?fileName=image.png" alt=Image><br> </div><div><br> </div><div>ajustado na sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12843', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.341', '2026-03-05 22:46:26', 411, null),
        (424, 'SME 1002 - O botão é só de adicionar veículos. O vínculo já é automático?', '<div>Ajustar a SME. C<span style="display:inline !important;">onforme alinhado com a Juliana,&nbsp;</span>o nome do botão para o mesmo do projeto, tanto em veículos quanto em máquinas e equipamentos. </div><div><br> </div><div>Solicitar também o ajuste no protótipo. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/ddee0233-1757-4be5-bb9f-8432564020e6?fileName=image.png" alt=Image><br> </div><div><br> </div><div>Sim, o vinculo ja é automático. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12845', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.342', '2026-03-05 22:46:26', 411, null),
        (425, 'SME 1007 - mas não por nº de contrato:', '<div>Conforme alinhado com a analista Juliana, nome da coluna deve ser contrato e mostrar o nome e o número do contrato, a SME será ajustada.&nbsp; </div><div>E o filtro também deve consultar pelos dois. </div><div><br> </div><div>Fazer na visão terceiro e visão empresa </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/87bbcbae-9c35-40a4-96a8-e262e68d75d9?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12846', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.342', '2026-03-05 22:46:26', 410, null),
        (426, 'SME 1004 -  Quando tem documento de desmobilização não redireciona como apontado na SME', '<div>Retirar da SME o item 16:&nbsp; </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/3080fc69-8ad2-4db8-8b0a-6e28effd0b3f?fileName=image.png" alt=Image><br> </div><div><br> </div><div>Ajustado a sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12847', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.343', '2026-03-05 22:46:26', 410, null),
        (427, 'SME 1007 - No sistema ainda possui o filtro ‘departamento regional’, por conta do usuário DN.', '<div>Ajustar na SME, o projeto tem alguns filtros que não estão na SME, como o citado pelo homologador: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/bd16235b-b3d3-4584-879e-0ebe8666459f?fileName=image.png" alt=Image><br> </div><div><br> </div><div>ajustado a sme </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12848', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.343', '2026-03-05 22:46:26', 409, null),
        (428, 'Responsividade - Steppers', null, null, null, 'completed', 'high', 'task', 'azure_devops', '12849', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.344', '2026-03-05 22:46:26', 324, null),
        (429, 'Responsividade - Mensagem de EmptyList', null, null, null, 'completed', 'high', 'task', 'azure_devops', '12850', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.344', '2026-03-05 22:46:26', 324, null),
        (430, 'SME 1002 - 3.b Não existe este botão para abrir essa janela para vincula', '<div>Excluir da SME, pois ao clicar no botão abre direto o formulário. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/8c67b592-29d8-4f33-89d4-fe26f03d01a0?fileName=image.png" alt=Image><br> </div><div>ajustado na sme </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/480e8730-3e5c-4084-b40c-66207b9a0d3a?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12851', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.345', '2026-03-05 22:46:26', 411, null),
        (431, 'SME 1002 - botão não encontrado para enviar a documentação.', '<div>Analisar e ajustar a documentação, esse botão acredito não existir mais nesse fluxo: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/413d2007-1b18-4e7b-9f55-15efa4d1152a?fileName=image.png" alt=Image><br> </div><div>ajustado na sme&nbsp; </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/acf2ad3d-cf28-4e27-80df-222d3a557c94?fileName=image.png" alt=Image> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12855', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.345', '2026-03-05 22:46:26', 411, null),
        (432, 'SME 0040 - A visualização do histórico', '<div>Analisar, pelo que entendi o homologador quer que melhore a informações iniciais dessa SME:&nbsp;<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/2b1e7209-dcbd-4e07-9662-dc058846f719?fileName=image.png" alt=Image> </div><div><br> </div><div>ajustado na SME conforme evidencia. [Att. Juliana, 08/04/2025]. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12858', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.346', '2026-03-05 22:46:26', 445, null),
        (433, 'SME 0040 - SME não fala do botão “Aplicar”', '<div>Favor incluir na SME informações sobre o botão aplicar que há nos filtros:&nbsp; </div><div><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/e6c31fa4-b938-4406-bfa6-fc8e0bdd9c6d?fileName=image.png" alt=Image><br> </div><div><br> </div><div>Ajustado na SME. [Att. Juliana - 08/04/2024] </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12863', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.347', '2026-03-05 22:46:26', 445, null),
        (434, 'SME 0040 - Por empresa, não fala na SME, e aparecem todas que ele nem foi mobilizado:', '<div>Dev: Ajustar o filtro para que mostre somente as empresas no qual o trabalhador esteja na mobilização, nos filtros Empresa e Unidades de estabelecimento. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12864', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.347', '2026-03-05 22:46:26', 445, null),
        (435, 'Item 1 - Erro ao realizar a importação de trabalhadores.', '<div><span style="font-family:Calibri;font-size:14.6667px;display:inline !important;">Ao realizar a importação de trabalhadores, visão SESI e Terceiro em “Trabalhadores do contrato” o sistema reporta o erro “Data de admissão informada não é uma data válida”. Contudo, o formato de data está conforme orientação de importação (Data de Início de Vínculo a data deverá estar no formato: dd/mm/aaaa).</span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12878', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.348', '2026-03-05 22:46:26', 448, null),
        (436, 'Item 2 - No documento de requisito não consta a tag "em elaboração".  A Tag corresponde a funcionalidade "Continuar e salvar depois"?', '<div>A juliana já havia colocado como ajustado na documentação na planilha da jornada. </div><div><br> </div><div>ajustado a sme </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/52685a63-1c63-40f7-a7d0-5772822369cd?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12904', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.349', '2026-03-05 22:46:26', 448, null),
        (437, 'Item 3 - No documento de requisito, consta: O botão <Adicionar veículos> o sistema deve mostrar as seguintes opções: Cadastrar novo, Vincular existente.​', '<div>Descrição completa:&nbsp; </div><div style="font-family:Calibri;font-size:14.6667px;">No documento de requisito, consta: O botão &lt;Adicionar veículos&gt; o sistema deve mostrar as seguintes opções: Cadastrar novo, Vincular existente.​ </div><div style="font-family:Calibri;font-size:14.6667px;"><br> </div><div style="font-family:Calibri;font-size:14.6667px;">No sistema tem a apenas a função: “Adicionar Veículos” que direciona para cadastrar veículos. Essa funcionalidade corresponde ao “Cadastrar novo”?​ </div><div style="font-family:Calibri;font-size:14.6667px;"><br> </div><div style="font-family:Calibri;font-size:14.6667px;">O item “Vincular existente, não identificamos no sistema. Essa funcionalidade corresponde a Mobilizar Veículos? </div><div style="font-family:Calibri;font-size:14.6667px;"><br> </div><div style="font-family:Calibri;font-size:14.6667px;">Ajustado na sme </div><div style="font-family:Calibri;font-size:14.6667px;"><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/5f32d241-ff90-4ce3-bcd7-5a55f734cf4b?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12905', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.349', '2026-03-05 22:46:26', 448, null),
        (438, 'Item 4 - No documento de requisito, consta: O botão <Adicionar máquinas e equipamentos> o sistema deve mostrar as seguintes opções: Cadastrar novo, Vincular existente.​', '<div>Descrição completa:&nbsp; </div><div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><span style="font-family:Calibri;font-size:11pt;">No documento de requisito, consta: O botão &lt;Adicionar máquinas e equipamentos&gt; o sistema deve mostrar as seguintes opções: Cadastrar novo, Vincular existente.​</span> </div><div style="font-family:Calibri;font-size:11pt;"><br> </div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><u style="text-decoration:underline;font-family:Calibri;font-size:11pt;">No sistema tem a apenas a função: “Adicionar máquinas e equipamentos” que direciona para cadastrar máquinas e equipamentos. Essa funcionalidade corresponde ao “Cadastrar novo”?​</u> </div><div style="font-family:Calibri;font-size:11pt;"><br> </div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><span style="font-family:Calibri;font-size:11pt;">O item “Vincular existente, não identificamos no sistema. Essa funcionalidade corresponde a Mobilizar máquina ou equipamento? ​</span> </div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><span style="font-family:Calibri;font-size:11pt;"><br></span> </div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><span style="font-family:Calibri;font-size:11pt;">ajustado em sme</span> </div><div style="font-family:&quot;Segoe UI&quot;, Calibri, Thonburi, Arial, Verdana, sans-serif, &quot;Mongolian Baiti&quot;, &quot;Microsoft Yi Baiti&quot;, &quot;Javanese Text&quot;;font-size:1px;"><span style="font-family:Calibri;font-size:11pt;"><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/ed028933-bc30-46e2-9110-864a55fb4755?fileName=image.png" alt=Image><br></span> </div> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12906', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.350', '2026-03-05 22:46:26', 448, null),
        (439, 'Item 5 - No documento de requisito, a nomenclatura dos grids de listagem de veículos está divergente do sistema:​  Requisito: Enviado  Sistema: Vinculado​  Requisito: Status  Sistema: Mobilizado', '<div>Não é uma falha e sim um ajustes na documentação. </div><div><br> </div><div>A juliana já ajustou, É necessário validar. </div><div><br> </div><div><br> </div><div>ajustado em sme </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/66d9b18c-3f43-4c77-ae30-f8602bbb65c5?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12907', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.350', '2026-03-05 22:46:26', 448, null),
        (440, 'Item 6 - No item avaliar documentos da empresa ao clicar na funcionalidade “Salvar e Continuar depois”', '<div>Descrição completa: </div><div><br> </div><div>&nbsp;<span style="font-family:Calibri;font-size:11pt;">No item </span><strong style="font-family:Calibri;font-size:11pt;">avaliar documentos</strong><span style="font-family:Calibri;font-size:11pt;"> da empresa ao clicar na funcionalidade </span><strong style="font-family:Calibri;font-size:11pt;">“Salvar e Continuar depois”,</strong><span style="font-family:Calibri;font-size:11pt;"> o sistema não apresenta a mensagem conforme informado no requisito: “Ao salvar, a sua avaliação estará disponível para edição e não perderá os itens já preenchidos.”</span> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12908', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.351', '2026-03-05 22:46:26', 448, null),
        (441, 'Item 7 - O sistema permite que a empresa terceira realize a mobilização de trabalhadores, veículos, máquinas e equipamentos sem a aprovação prévia dos documentos solicitados?', '<div>Descrição completa:&nbsp; </div><div><br><div style="font-family:Calibri;font-size:13.3333px;">No cadastro da empresa terceira, é possível cadastrar trabalhadores, veículos, máquinas e equipamentos. Quando a empresa terceira insere a documentação de mobilização sem que o SESI tenha solicitado documentos no critério ou formulário, o sistema está permitindo a mobilização, ficando o SESI apenas aguardando a aprovação dos documentos que foram solicitados no requisito e formulário. ​ </div><div style="font-family:Calibri;font-size:13.3333px;"><br> </div><div style="font-family:Calibri;font-size:13.3333px;">O sistema permite que a empresa terceira realize a mobilização de trabalhadores, veículos, máquinas e equipamentos sem a aprovação prévia dos documentos solicitados? </div><div style="font-family:Calibri;font-size:13.3333px;"><br> </div><div style="font-family:Calibri;font-size:13.3333px;"><br> </div><div style="font-family:Calibri;font-size:13.3333px;"><br> </div><div style="font-family:Calibri;font-size:13.3333px;">Avaliar com os homologadores. </div> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12910', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 20, 3, '2026-03-05 22:46:17.351', '2026-03-05 22:46:26', 448, null),
        (442, 'Homologação DN - SME 1009', '<div>documentação homologador:&nbsp;<a href="https://docs.google.com/document/d/1c0c8jdBbjyzDYjznC2yaycjgNXSTjKZW/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true">https://docs.google.com/document/d/1c0c8jdBbjyzDYjznC2yaycjgNXSTjKZW/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12801', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'User Story', 'JULIA STEPHANIE ANTONIO', 'julia.antonio@sc.senai.br', 24, 3, '2026-03-05 22:46:17.332', '2026-03-05 22:46:26', 443, null),
        (443, 'Correções de homologação da sprint 09 DN', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '12808', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Feature', null, null, 24, 3, '2026-03-05 22:46:17.334', '2026-03-05 22:46:26', 313, null),
