        (445, 'Homologação DN - SME 0040', '<div>Documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1RFqm6Y1ytM5Uh5k-uYbuNjBky0NNjccP/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true">https://docs.google.com/document/d/1RFqm6Y1ytM5Uh5k-uYbuNjBky0NNjccP/edit?usp=sharing&amp;ouid=102949589511025415410&amp;rtpof=true&amp;sd=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12857', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:17.346', '2026-03-05 22:46:26', 443, null),
        (446, '(MELHORIA) - SME 0040 - A tela de edição para ver o histórico do trabalhador não tem o nome do trabalhador. (Melhoria)', '<div>Análise favor verificar se essa melhoria deve ser realmente solicitada:&nbsp; </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/8375c43f-61fd-49a7-a502-ca13ca0d9258?fileName=image.png" alt=Image><br> </div><div><b><br></b> </div><div><b>MELHORIA</b> </div><div><span style="display:inline !important;">Hoje não mostra o nome do trabalhador no histórico da mobilização porque ja esta na tela do cadastro do trabalhador, mas como melhoria podemos acrescentar um header com o nome do trabalhador, conforme temos na mobilização o nome da empresa:&nbsp;</span><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/9a5c4b12-30e7-43e0-b620-69cb0598cdf4?fileName=image.png" alt=Image style="box-sizing:border-box;max-width:100%;align-self:center;"><br> </div><div><br> </div><div>[Att. Juliana - 08/04/2025 </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12861', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 24, 3, '2026-03-05 22:46:17.346', '2026-03-05 22:46:26', 666, null),
        (447, 'SME 0040 -', null, null, null, 'cancelled', 'high', 'task', 'azure_devops', '12866', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.348', '2026-03-05 22:46:26', 445, null),
        (448, 'Jornada 3', '<div>Planilha jornada 3:&nbsp;<a href="https://cnicombr.sharepoint.com/:x:/r/sites/sussiexterno/_layouts/15/Doc.aspx?sourcedoc=%7bAC34157E-F9E9-4E5B-BF30-47FDF4470C82%7d&amp;file=Homologa%C3%A7%C3%A3o%20Jornadas%20DR_MG.xlsx&amp;action=default&amp;mobileredirect=true">https://cnicombr.sharepoint.com/:x:/r/sites/sussiexterno/_layouts/15/Doc.aspx?sourcedoc=%7BAC34157E-F9E9-4E5B-BF30-47FDF4470C82%7D&amp;file=Homologa%C3%A7%C3%A3o%20Jornadas%20DR_MG.xlsx&amp;action=default&amp;mobileredirect=true</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '12877', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:17.348', '2026-03-05 22:46:26', 444, null),
        (449, 'Problema reportado em Unidade de Estabelecimento > Níveis Hierárquicos no sistema', '<div>Bug reportado na tela de Gerenciar Níveis Hierarquicos, dentro de unidade de estabelecimento. Vídeo contém o bug reportado.<br><br>&nbsp;<a href="https://drive.google.com/file/d/1JZMC9CYaUpuWgZmZa7NFD0wDcqt3N1lW/view?usp=drive_link">https://drive.google.com/file/d/1JZMC9CYaUpuWgZmZa7NFD0wDcqt3N1lW/view?usp=drive_link</a><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12913', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.351', '2026-03-05 22:46:26', 494, null),
        (450, 'Responsividade - Sistema (Critérios de Mobilização)', null, null, null, 'completed', 'high', 'task', 'azure_devops', '12730', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.388', '2026-03-05 22:46:26', 324, null),
        (451, 'Ao cadastrar trabalhador em Unidade de Estabelecimento, já deveria vincular automaticamente a unidade no qual cadastrou.', '<div><a href="https://drive.google.com/file/d/1sg8IjlgJhWmAGz84WWuMddtYYGIYh0QP/view?usp=drive_link">https://drive.google.com/file/d/1sg8IjlgJhWmAGz84WWuMddtYYGIYh0QP/view?usp=drive_link</a><br><br>Ao cadastrar trabalhador em Unidade de Estabelecimento, já deveria vincular automaticamente a unidade no qual cadastrou. [Validado com a Juliana] </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12936', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.655', '2026-03-05 22:46:26', 494, null),
        (452, 'Inserir mensagem ao usuário ref. ao ato de tentar excluir algum nível de hierarquia que já pertence a trabalhadores. Aparece que foi excluído com sucesso, mas na verdade não foi.', '<div>Inserir mensagem ao usuário ref. ao ato de tentar excluir algum nível de hierarquia que já pertence a trabalhadores. Aparece que foi excluído com sucesso, mas na verdade não foi.<br><br>Validar com a análise qual a mensagem apropriada.<br><br>Exemplo: Não é possível excluir a &lt;sub-hierarquia&gt; pois a mesma já se encontra vinculada a trabalhadores.<br><br>Vídeo demonstrando em evidência.<br><br><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12955', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.655', '2026-03-05 22:46:26', 494, null),
        (453, 'Responsividade - DocumentAttachment', null, null, null, 'completed', 'high', 'task', 'azure_devops', '12960', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.656', '2026-03-05 22:46:26', 324, null),
        (454, '[MELHORIA] - Falha de Segurança Crítica: O acesso de imagens e documentos dentro do sistema está publico, qualquer usuário pode acessar qualquer dado.', '<div>Falha de Segurança Crítica: O acesso de imagens e documentos dentro do sistema está publico, qualquer usuário pode acessar qualquer dado.<br> </div>', null, null, 'pending', 'high', 'task', 'azure_devops', '12961', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Task', 'FABRISIO PEREIRA BEZ FONTANA FILHO', 'fabrisio.filho@sc.senai.br', 24, 3, '2026-03-05 22:46:17.656', '2026-03-05 22:46:26', 666, null),
        (455, '[MELHORIA] - Falha de Segurança Crítica:  A alteração de acesso do usuario está desprotegida, sendo possivel qualquer usuario que tenha conhecimento técnico acessar os dados de outras empresas.', '<div>Falha de Segurança Crítica: &nbsp;A alteração de acesso do usuario está desprotegida, sendo possivel qualquer usuario que tenha conhecimento técnico acessar os dados de outras empresas.<br> </div>', null, null, 'pending', 'high', 'task', 'azure_devops', '12962', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Task', 'FABRISIO PEREIRA BEZ FONTANA FILHO', 'fabrisio.filho@sc.senai.br', 24, 3, '2026-03-05 22:46:17.656', '2026-03-05 22:46:26', 666, null),
        (456, '[MELHORIA] - Segurança: Alterar token para cookie, para garantir uma maior segurança e controle de informações.', '<div>Segurança: Alterar token para cookie, para garantir uma maior segurança e controle de informações.<br> </div>', null, null, 'pending', 'high', 'task', 'azure_devops', '12963', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Task', 'FABRISIO PEREIRA BEZ FONTANA FILHO', 'fabrisio.filho@sc.senai.br', 24, 3, '2026-03-05 22:46:17.657', '2026-03-05 22:46:26', 666, null),
        (457, 'Refatoração das notificações', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '12973', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.657', '2026-03-05 22:46:17.657', null, null),
        (458, 'Auditoria das notificações de envio de documentos de mobilização', '<div>Foram refatoradas as 5 notificações de envio de documentos de mobilização (empresa, subcontratado, trabalhador, veículo, equipamento). </div><div>Não houveram mudanças visuais, apenas de código. </div><div><br> </div><div><a href="https://docs.google.com/spreadsheets/d/1Z_EQnFjIpDw2s6_lH4jFWuxaRIc3pwdLY4vTSKTcTjQ/edit?gid=649197192#gid=649197192">Link para a planilha contendo as notificações</a> </div><div>Branch (backend apenas): fix/refactor-notifications </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12974', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.657', '2026-03-05 22:46:26', 457, null),
        (459, 'Realizar SONAR e corrigir bugs, code smells...', '<div>Realizar SONAR e corrigir bugs, code smells...<br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12991', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.658', '2026-03-05 22:46:26', 457, null),
        (460, 'Item 6: ​Ajustar notificação.', '<div><span style="font-size:10pt;font-family:Nunito,Arial;font-weight:normal;text-align:center;"><span style="font-weight:bold;">Item 6: </span><span>​Conforme documento de requisito “Se o e-mail já estiver associado a um usuário cadastrado no sistema, o sistema deve enviar um e-mail informando sobre o cadastro da empresa com esse e-mail responsável”.  ​Ao realizar o cadastro com um e-mail já existente no sistema, nenhuma notificação foi recebida. O e-mail utilizado para teste, que já está cadastrado como usuário, foi sistemasst@fiemg.com.br. Empresa de teste MINERAÇÃO MBA (MATRIZ). </span></span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '12993', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.658', '2026-03-05 22:46:26', 325, null),
