        (487, 'Responsividade - Notificações', null, null, null, 'completed', 'high', 'task', 'azure_devops', '13190', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.671', '2026-03-05 22:46:26', 324, null),
        (488, 'Reteste Homologação DN', '<div>Essa feature trata do retorno do Neto para os itens apontados na homologação e corrigidos. </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '13232', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Feature', null, null, 20, 3, '2026-03-05 22:46:17.671', '2026-03-05 22:46:26', 313, null),
        (489, 'Reteste - SME 0001 - Cadastrar Cliente - Empresa', '<div>Link documento:&nbsp;<a href="https://docs.google.com/document/d/1L6sgDPwh-MYPhCwOicU2ZPRSSYrir1zf/edit">https://docs.google.com/document/d/1L6sgDPwh-MYPhCwOicU2ZPRSSYrir1zf/edit</a> </div><div><br> </div><div>Link trello:&nbsp;<a href="https://trello.com/c/fDW2MeQD/29-sme-0001-cadastrar-cliente-empresa">https://trello.com/c/fDW2MeQD/29-sme-0001-cadastrar-cliente-empresa</a> </div><div><br> </div><div><b>Ainda há 2 itens pendentes de por parte do DN</b> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '13234', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:17.672', '2026-03-05 22:46:26', 488, null),
        (490, '1 - Ajuste informações de usuário administrador da empresa e responsável da empresa', '<div>Implementar para que ao buscar um e-mail já cadastrado no sistema, traga todas as informações, nome, cargo e telefone. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/d4762677-dd03-4086-aaf2-c5f49d5c3fa2?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13239', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.672', '2026-03-05 22:46:26', 489, null),
        (491, '2 - Verificar o envio dos e-mail do cadastro de empresa', 'Essa foi a observação do homologador:&nbsp;<p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="font-weight:700;">Não recebimento de email para “usuário adm da empresa’ substituído sendo que ele já está cadastrado no sistema.</strong> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="font-weight:700;"><br></strong> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><b>Para dev/auditoria, há uma outra demanda sobre os e-mails:&nbsp;<a href="https://dev.azure.com/senaisc-solucoes-digitais/Tribo%20SEIF/_workitems/edit/12590">https://dev.azure.com/senaisc-solucoes-digitais/Tribo%20SEIF/_workitems/edit/12590</a></b> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;">Após a finalização desse item, testar o envio dos e-mails e verificar se estão todos funcionando corretamente incluindo o apontado pelo homologador. </p>', null, null, 'completed', 'high', 'task', 'azure_devops', '13240', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.672', '2026-03-05 22:46:26', 489, null),
        (492, 'Reteste - SME 0002 – Cadastrar Cliente – Estabelecimento', '<div>trello:&nbsp;<a href="https://trello.com/c/pQqR95KC/30-sme-0002-cadastrar-cliente-estabelecimento">https://trello.com/c/pQqR95KC/30-sme-0002-cadastrar-cliente-estabelecimento</a> </div><div><br> </div><div>documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1Hb1jwL-gEQvN3fCnK_0WUZio1Aa4nDG0/edit">https://docs.google.com/document/d/1Hb1jwL-gEQvN3fCnK_0WUZio1Aa4nDG0/edit</a> </div><div><br> </div><div><b style="box-sizing:border-box;">Ainda há 1 item pendente de por parte do DN</b><br> </div><div><br> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '13241', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:17.673', '2026-03-05 22:46:26', 488, null),
        (493, '1 - Não recebimento de email para “usuário adm da empresa’ substituído sendo que ele já está cadastrado no sistema.', '<div><div style="box-sizing:border-box;">Essa foi a observação do homologador:&nbsp; </div><p style="box-sizing:border-box;margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="box-sizing:border-box;font-weight:700;"><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="font-weight:700;">Não recebimento de email para “usuário adm da empresa’ substituído sendo que ele já está cadastrado no sistema.</strong> </p></strong> </p><p style="box-sizing:border-box;margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="box-sizing:border-box;font-weight:700;"><br style="box-sizing:border-box;"></strong> </p><p style="box-sizing:border-box;margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><b style="box-sizing:border-box;">Para dev/auditoria, há uma outra demanda sobre os e-mails:&nbsp;<a href="https://dev.azure.com/senaisc-solucoes-digitais/Tribo%20SEIF/_workitems/edit/12590" style="box-sizing:border-box;color:rgb(0, 90, 158);text-decoration:underline;cursor:pointer;">https://dev.azure.com/senaisc-solucoes-digitais/Tribo%20SEIF/_workitems/edit/12590</a></b> </p><p style="box-sizing:border-box;margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br style="box-sizing:border-box;"> </p><p style="box-sizing:border-box;margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;">Após a finalização desse item, testar o envio dos e-mails e verificar se estão todos funcionando corretamente incluindo o apontado pelo homologador. </p><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13242', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.674', '2026-03-05 22:46:26', 492, null),
        (494, 'Auditoria', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '12919', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 003.2025', null, null, 'User Story', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 22, 3, '2026-03-05 22:46:17.654', '2026-03-05 22:46:26', 665, null),
