        (540, 'Reteste - SME 1008 - Exportar tabelas', '<div>Homologador:&nbsp;<a href="https://docs.google.com/document/d/1W4ulVw1-d8yDEZrMPBMLr6fHFqNLo92x/edit">https://docs.google.com/document/d/1W4ulVw1-d8yDEZrMPBMLr6fHFqNLo92x/edit</a> </div><div><br> </div><div>Trello:&nbsp;<a href="https://trello.com/c/A8BYGH3e/96-sme-1008-exportar-tabelas">https://trello.com/c/A8BYGH3e/96-sme-1008-exportar-tabelas</a> </div>', null, null, 'completed', 'high', 'feature', 'azure_devops', '13338', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:17.988', '2026-03-05 22:46:26', 488, null),
        (541, 'Formulários: Consegui baixar, mas o nome do arquivo fica como: "Contratos de terceiros"', '<p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;">homologador: Formulários -&gt; Consegui baixar, mas o nome do arquivo fica como: &quot;Contratos de terceiros&quot; </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;">Para dev: alterar o nome do arquivo dessa exportação, verificar também com os outros perfis Sesi se o nome está correto. </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br> </p><div style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/50dcdd33-5370-418e-ab1b-1c005a082bfd?fileName=image.png" alt=Image><br> </div><div style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br> </div><br>', null, null, 'completed', 'high', 'task', 'azure_devops', '13339', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.988', '2026-03-05 22:46:26', 540, null),
        (542, 'Ao editar contrato SESI na visão SESI está me retornando um erro me impedindo de avançar.', '<div>Ao editar contrato SESI na visão SESI está me retornando um erro me impedindo de avançar.<br><br><div><a href="https://drive.google.com/file/d/1-S9vedpuky6NXXRGMG0trRlbJ_1OYrXf/view?usp=drive_link">https://drive.google.com/file/d/1-S9vedpuky6NXXRGMG0trRlbJ_1OYrXf/view?usp=drive_link</a><br> </div><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13363', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:17.991', '2026-03-05 22:46:26', 494, null),
        (543, 'Busca por nome não está funcionando', '<div>A busca por nome do contrato não está funcionando. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/304c571b-a8dc-461f-b016-781d8474f735?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13366', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.991', '2026-03-05 22:46:26', 494, null),
        (544, 'Gestão do Projeto Mobilização e Desmobilização', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '13369', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Feature', null, null, 24, 3, '2026-03-05 22:46:17.992', '2026-03-05 22:46:26', 313, null),
        (545, 'Gestão Mobilização e Desmobilização', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '13370', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 003.2025', null, null, 'User Story', null, null, 22, 3, '2026-03-05 22:46:17.992', '2026-03-05 22:46:26', 544, null),
        (546, 'Erro ao inativar um trabalhador com o usuário Sesi', '<div>Para análise: </div><div><br> </div><div>Favor verificar se o usuário Sesi DN pode conseguir inativar um trabalhador, caso positivo favor passar para o desenvolvimento.: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1bb9ad85-0485-4627-b477-49bc4967e697?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13385', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.993', '2026-03-05 22:46:26', 494, null),
        (547, 'Ao remover um estabelecimento do contrato SESI, cujo provavelmente já deve ter criado algum vínculo, está dando um erro em tela, tratar a mensagem de erro.', '<div>Ao remover um estabelecimento do contrato SESI, cujo provavelmente já deve ter criado algum vínculo, está dando um erro em tela, tratar a mensagem de erro.<br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13395', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; RETRABALHO', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.994', '2026-03-05 22:46:26', 494, null),
        (548, 'Ao excluir uma pergunta do formulário, o sistema não está conseguindo reordenar a numeração lógica dos itens, estourando um erro em tela.', '<div>Ao excluir uma pergunta do formulário, o sistema não está conseguindo reordenar a numeração lógica dos itens, estourando um erro em tela.<br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13396', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:17.994', '2026-03-05 22:46:26', 494, null),
        (549, 'Erro no salvar imagem contrato subcontratado', '<div>Quando insiro uma imagem no cadastro novo de contrato essa imagem não persiste, se eu insiro através do editar ela salva: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/e15deb0b-bdc0-4a3b-be79-60ee7c45542c?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13407', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:17.994', '2026-03-05 22:46:26', 494, null),
        (550, '2 - Para evitar divergências, poderíamos considerar bloquear os campos de cadastro no estabelecimento e na sua unidade, permitindo apenas a edição dos dados da empresa.', 'informação do homologador:&nbsp;<p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><strong style="font-weight:700;">Assistindo ao vídeo do Bruno Medeiros, ele explica detalhadamente como o sistema está funcionando atualmente, entretanto, conforme discutido via Teams no grupo &quot;Dúvidas Homologação SEIF&quot; em 10/04/25, o primeiro estabelecimento e a primeira unidade de estabelecimento são criados automaticamente como espelho da empresa. Como estes se referem à matriz da empresa, para que a hierarquia criada pelo sistema funcione corretamente, esses campos devem sempre refletir a empresa de forma espelhada.</strong><br><strong style="font-weight:700;">Para evitar divergências, poderíamos considerar bloquear os campos de cadastro no estabelecimento e na sua unidade, permitindo apenas a edição dos dados da empresa. Caso a empresa deseje criar um novo estabelecimento no futuro, então poderemos ter dados diferentes. Reforço isso porque o primeiro estabelecimento e sua respectiva unidade sempre serão considerados como a matriz da empresa.</strong> </p><p style="margin:0px;letter-spacing:-0.005em;text-overflow:ellipsis;"><br> </p>', null, null, 'completed', 'high', 'task', 'azure_devops', '13244', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.032', '2026-03-05 22:46:26', 492, null),
        (551, 'Integracao do nukleo com a importacao de empresa e terceiro', '<div>Integrar os campos opcionais de endereco com as informacoes trazidas pelo Nukleo, atendendo a seguinte regra:<br><br>Se o usuário preencher esses campos o sistema deverá considerar o que foi preenchido pelo usuário. </div><div>Se esses campos estiverem vazios, o sistema deverá trazer as informacoes de endereco do Nukleo (se houver). </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13413', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.284', '2026-03-05 22:46:26', 494, null),
        (552, 'Erro responsável terceiro', '<div>Quando eu coloco um responsável do terceiro que já está vinculado a uma empresa ele apresenta o erro abaixo, quanto a isso está ok, o problema é que mesmo alterando os dados do responsável do terceiro, o erro continua aparecendo.: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/00c075fd-421b-4246-b497-08096065ff16?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13415', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.285', '2026-03-05 22:46:26', 494, null),
        (553, 'Não está salvando os dados Nome Fantasia e Razão Social da seção de Fabricante/Importador de Máquinas e Equipamentos.', '<div>Não está salvando os dados Nome Fantasia e Razão Social da seção de Fabricante/Importador de Máquinas e Equipamentos.<br> </div>', null, null, 'cancelled', 'high', 'task', 'azure_devops', '13419', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'JOSE RENAN SANTOS SILVA', 'jose.renan@sc.senai.br', 20, 3, '2026-03-05 22:46:18.285', '2026-03-05 22:46:26', 494, null),
        (554, 'Botão descartar não está limpando todos os campos do cadastro do trabalhador', '<div>os campos continuam com a informação anterior após clicar no descartar: </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/4fcb6c38-2443-43a4-b3a3-49bebf9e7d12?fileName=image.png" alt=Image><br> </div><div><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13423', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.286', '2026-03-05 22:46:26', 494, null),
        (555, 'Item 6 - Liberar documento regionais em formulário.', '<div style="flex-shrink:0;margin-right:8px;display:flex;color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;background-color:rgb(34, 37, 41);"><div style="text-align:right;margin:-4px 0px -4px -20px;opacity:1;"><br> </div> </div><div style="flex:1 1 0px;min-width:0px;margin:-12px -8px -16px -16px;padding:8px 8px 8px 16px;color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;background-color:rgb(34, 37, 41);"><div style="max-width:none;margin-bottom:4px;"><div style="max-width:none;"><div><div style="display:flex;"><div dir=auto style="text-align:left;"><div><b>[28/04/2025 - Juliana]<span>&nbsp;</span></b>- Em contato com o Neto via teams, o mesmo conversou com a Carol (SESI MG), para que seja feita a seguinte alteração: No formulário o sistema deve permitir vincular documentos de propriedade &quot;regional&quot; </div> </div> </div> </div> </div> </div> </div><br>', null, null, 'completed', 'high', 'task', 'azure_devops', '13425', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.286', '2026-03-05 22:46:26', 326, null),
        (556, 'Quando vai visualizar um manual .rar no sistema [Manuais do sistema] é aberto um modal de visualização em branco.', '<div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/a1cb56b6-f495-462b-9ba5-30bae74aad88?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13431', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.287', '2026-03-05 22:46:26', 494, null),
        (557, 'Erro ao remover todos os vínculos de trabalho do trabalhador', '<div>Ao remover todos o vínculos do trabalhador é mostrado uma tela em branco: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/535dcd8e-5954-4234-abce-d97396c649a0?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13432', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:18.287', '2026-03-05 22:46:26', 494, null),
        (558, 'Em uma mobilização ao tentar procurar um formulário é retornado mais de um critério.', 'No sistema a gente não tem exclusão, verificar a cron para ativar e inativar o critério. <br><div><br><span style="display:inline !important;">Deve ser implementada uma ação adicional ao tooltip de inativação, que, a</span><span style="display:inline !important;">o inativar um critério, o sistema deve alterar a data de final de vigência para a data do momento da inativação.&nbsp;</span><br style="box-sizing:border-box;"><br style="box-sizing:border-box;"><span style="display:inline !important;">Deve ser exibida uma mensagem de confirmação e junto dessa, a informação ao usuário que a data de final de vigência será alterada para a data de hoje.<br></span><br>Realizado ajuste na SME.<br><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/a8c01581-7dab-45b8-abda-b8ff74350e9e?fileName=image.png" alt=Image><br><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13434', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.287', '2026-03-05 22:46:27', 494, null),
        (559, 'SME 1002 - Mobilização Inicial - Visão Terceiro', '<div>Documento homologador:&nbsp;<a href="https://docs.google.com/document/d/1cmo-vGhbJasspTS8bOMGPnQH2pqAG5X3/edit">https://docs.google.com/document/d/1cmo-vGhbJasspTS8bOMGPnQH2pqAG5X3/edit</a> </div><div><br> </div><div><br> </div><div>Trello:&nbsp;<a href="https://trello.com/c/RWb7oE9l/70-sme-1002-mobiliza%C3%A7%C3%A3o-inicial-vis%C3%A3o-terceiro">https://trello.com/c/RWb7oE9l/70-sme-1002-mobiliza%C3%A7%C3%A3o-inicial-vis%C3%A3o-terceiro</a> </div>', null, null, 'cancelled', 'high', 'feature', 'azure_devops', '13441', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'User Story', null, null, 20, 3, '2026-03-05 22:46:18.288', '2026-03-05 22:46:27', 488, null),
        (560, 'Erro ao excluir um nível hierarquico', '<div>Está ocorrendo o seguinte erro: </div><div><br> </div><div>Se tentar excluir esses níveis:<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/5fe67af5-273c-46f3-901b-3f6d75234561?fileName=image.png" alt=Image> </div><div><br> </div><div>Ocorre o erro quando não tenho nada na árvore de hierarquias abaixo: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1675154e-c672-4863-a9c4-a04f22c7a1a6?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13453', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.288', '2026-03-05 22:46:27', 494, null),
        (561, 'Não está excluindo perguntas de formulários (Mobilização e Desmobilização)', '<div>Não está excluindo perguntas de formulários (Mobilização e Desmobilização). </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13465', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.289', '2026-03-05 22:46:27', 494, null),
        (562, 'Implementação de colunas e filtros nas entidades Máquinas/Equipamentos e Veículos nas visões SESI, EMPRESA e TERCEIRO.', '<div>Adicionar colunas: Cadastrado, Situação e Status nas entidades: Veículos e Máquinas/Equipamentos nas visões SESI, Empresa e Terceiro.<br><br>Segue protótipo: <a href="https://www.figma.com/design/jwdtXfKPCt6lBYdBKTmw5I/SEIF---Fase-3---M%C3%B3dulo-0.-Configura%C3%A7%C3%B5es?node-id=10-92052&amp;p=f&amp;m=dev">https://www.figma.com/design/jwdtXfKPCt6lBYdBKTmw5I/SEIF---Fase-3---M%C3%B3dulo-0.-Configura%C3%A7%C3%B5es?node-id=10-92052&amp;p=f&amp;m=dev</a><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/3c2a452c-32a6-466b-97bf-050b0b40e19e?fileName=image.png" alt=Image><br>Validar o campo Filtros também, pois no protótipo tem a mais do que foi desenvolvido.<br><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13469', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.289', '2026-03-05 22:46:27', 494, null),
        (563, 'Item 15 - Remover obrigatoriedade do anexo para a desativação do documento dentro de Dados Empresariais e realização de CRON para inativação dos documentos.', '<div>Item 15 - Deixar opcional o anexo para a inativação do documento dentro de Dados Empresariais.<br> </div><div><br><b>Visões:</b> Empresa, Estabelecimento e Unidade de Estabelecimento e Terceiros.<br><br>O que precisa ser feito?<br><ol><li>Remover obrigatoriedade do anexo para a inativação do documento dentro de Dados Empresariais em todas as visões.<br><br> </li><li>Realizar CRON que roda diariamente apenas uma única vez para inativação dos documentos vencidos. (Seguir padrão da CRON que temos em Contratos, pode ser utilizado este mesmo método no momento). </li> </ol><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/ff9205a8-400e-419e-9e71-7ee9aff97c85?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13470', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.289', '2026-03-05 22:46:27', 325, null),
        (564, 'Perfis e Permissões: Resolver conflitos ou refazer a demanda. Precisará testar todo o sistema, risco alto de quebrar partes do sistema.', '<div>Perfis e Permissões: Resolver conflitos ou refazer a demanda. Precisará testar todo o sistema, risco alto de quebrar partes do sistema.<br> </div><div><br><b>Branchs antigas:</b><br><br><span><b>frontend: </b></span>feature/1093829_3<br><br><div><b>backend:</b> <span>feature/1093829<br><br><b>Branchs novas:</b><br><br><span><b>frontend: </b></span>feature/13478<br><br><div><b>backend:</b>&nbsp;feature/1093829_rebase<br><br><a href="https://cnicombr.sharepoint.com/:w:/r/sites/sussiexterno/_layouts/15/Doc.aspx?sourcedoc=%7b757AD1DF-3B8C-4D69-8BED-480ED8D46951%7d&amp;file=SME%201010%20-%20Perfis%20e%20Permiss%C3%B5es.docx&amp;action=default&amp;mobileredirect=true">SME</a> e <a href="https://docs.google.com/spreadsheets/d/1ppkU5kmt_Cos0UU7cJyb74CJsGYJ6nU2v4kSXYdZusc/edit?gid=1380537033#gid=1380537033">Planilha</a> </div><br></span> </div> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13478', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.290', '2026-03-05 22:46:27', 494, null),
        (565, 'Verificar o motivo do cadastro de um admin empresa estar muito lento', '<div>Está demorando muito para cadastrar um novo usuário admin empresa na visão empresa: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/9ea37900-cfc5-44dd-9a21-57496d9e9a71?fileName=image.png" alt=Image><br> </div>', null, null, 'cancelled', 'high', 'task', 'azure_devops', '13488', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.290', '2026-03-05 22:46:27', 494, null),
        (566, 'Item 0006 - Ajustar os criterios para permitir a utilização de documentos regionais', '<div><span style="font-family:Calibri;font-size:13.3333px;text-align:left;display:inline !important;">Realizando  teste criação de critérios, identificamos  que o sistema não está permitindo realizar o vínculo necessário dos documentos criados nas categorias (regional e empresa). <br></span> </div><br><div>Para dev:<br><br>Será necessário implementar uma solução similar a utilizada na task&nbsp;<a href="https://dev.azure.com/senaisc-solucoes-digitais/Tribo%20SEIF/_workitems/edit/13425">13425</a>&nbsp;para utilização de formulários do tipo regional nos formulários. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13518', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.291', '2026-03-05 22:46:27', 326, null),
        (567, 'Ajuste erro cadastro máquinas e equipamentos mobilização', '<div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">1 - Quando cadastro uma máquina ou equipamento e clico em salvar não fecha a modal.</span><br> </div><div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;"><br></span> </div><div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">2 - Padronizar o título todos os documentos na mobilização.</span> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13533', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.291', '2026-03-05 22:46:27', 494, null),
        (568, 'Incluir o CNPJ da unidade de estabelecimento na listagem de unidades em Critérios de Mobilização.', '<div><br> </div><div>Incluir o CNPJ da unidade de estabelecimento na listagem de unidades em Critérios de Mobilização.<img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/124d9cbc-bb48-4f99-a61f-fc9a00c2f30f?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13536', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.291', '2026-03-05 22:46:27', 494, null),
        (569, 'Inserir validação no frontend para o campo Número do contrato no módulo de Contrato Terceiro x Empresa na visão Empresa.', '<div><br> </div><div>Inserir validação no frontend para o campo Número do contrato no módulo de Contrato Terceiro x Empresa na visão Empresa. </div><div><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/5ac26a83-3889-474b-af01-f46dd6da18fc?fileName=image.png" alt=Image> </div><div>Na visão SESI e Terceiro a validação existe:<br><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/9648b3e4-6891-436b-850b-8342e3b614b1?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13550', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.292', '2026-03-05 22:46:27', 494, null),
        (570, 'Ajuste Tabela trabalhador visão fornecedor', '<div>1 - Para padronizar e melhorar a usabilidade, na tabela de trabalhadores na visão fornecedor, trocar a coluna &quot;Data de admissão&quot; para &quot;Tipo&quot;, de acordo com a tabela trabalhadores da visão empresa: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/b1671bee-2d45-46a7-b2b6-15162409fcbf?fileName=image.png" alt=Image><br> </div><div><br> </div><div>2 - Implementar também o filtro tipo na visão fornecedor: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/f16832d0-7564-4d8f-ba16-d5694ec70749?fileName=image.png" alt=Image><br> </div><div><br> </div><div>3 - Ajustar o bug: Na visão Sesi quando eu filtro o tipo subcontratado e tento acessar o trabalhador na empresa, está me direcionando para a empresa e não para o fornecedor responsável pelo trabalhador: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/23388744-0cf8-4f6c-a959-37bc1b5aac5a?fileName=image.png" alt=Image> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/b4d5fb29-75ff-4178-8c4b-fa961d9b8222?fileName=image.png" alt=Image><br> </div><div><br> </div><div><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13551', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.292', '2026-03-05 22:46:27', 494, null),
        (571, '2 - Erro na importação da planilha para checar preenchimento e validações do CBO:', '<div>Para dev: </div><div><br> </div><div>1 - há alguns CBOs que existem mas o sistema está retornando como não encontrado, exemplo: 223660 </div><div><br> </div><div>2 - Na importação pela planilha quando o CBO é inexistente ele está cadastrando como vazio, deveria ter a mensagem de cbo não encontrado como tem no cadastro pelo sistema, lembrando que ele não é obrigatório, mas quando estiver preenchido tem que validar. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13583', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.293', '2026-03-05 22:46:27', 530, null),
        (572, 'Revisar todos os fluxos de cadastro de usuario no sistema', '<div><p> </p><p>Durante os testes na aplicação, foram identificados alguns problemas no fluxo de cadastro de usuários, especialmente nos cadastros do tipo <strong>ADMIN</strong>. Atualmente, um único cargo é atribuído ao usuário e compartilhado entre todos os vínculos com diferentes entidades. No entanto, essa abordagem precisa ser ajustada para que cada vínculo possua seu próprio cargo específico. </p><p>Outro ponto identificado é a necessidade de permitir que usuários do tipo <strong>fornecedor</strong> tenham múltiplos fornecedores vinculados ao mesmo login. Esses usuários devem conseguir acessar o sistema e, no momento do login, selecionar com qual fornecedor desejam se autenticar — comportamento semelhante ao fluxo atual de seleção de empresas. </p><p>Diante disso, solicita-se a revisão completa do fluxo, a identificação de possíveis melhorias no código e a implementação das correções descritas acima. </p><p> </p> </div><div><a target=_blank href="https://www.figma.com/design/PVRxkYHbqwBpPXLQMZh5mR/SEIF---Fase-3---M%C3%B3dulo-1.-Mobiliza%C3%A7%C3%A3o-e-Desmobiliza%C3%A7%C3%A3o?node-id=2532-72763&amp;m=dev&amp;t=JtQL3siPKCjY4ceH-1" rel="noopener noreferrer" style="color:rgb(29, 155, 209);text-decoration:underline;font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(34, 37, 41);">múltiplos cargos no cadastro do usuário</a><br><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/6168d5a1-dbe4-40b6-b3b0-33f8362a1b9f?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13613', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'RETRABALHO', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.294', '2026-03-05 22:46:27', 494, null),
        (573, 'Erro ao excluir um nível hierarquico', '<div>Ao tentar excluir um nível hierárquico que já está sendo utilizado ocorre o erro abaixo: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/7eff57ae-fd0c-49c0-bd7a-1fa5d8566734?fileName=image.png" alt=Image><br> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/06cd3b1d-e486-4e7b-8354-6e88a96eee7b?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13641', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.294', '2026-03-05 22:46:27', 494, null),
        (574, 'Preparação para o Treinamento do Sistema (juliana)', '<div>Lançamento de horas referente atividades da preparação e apresentação do treinamento SEIF - Gestão de Terceiros. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13646', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'DIEGO ALVES DA LUZ', 'diego.l@sc.senai.br', 20, 3, '2026-03-05 22:46:18.295', '2026-03-05 22:46:27', 593, null),
        (575, 'Ajustar CRON Criterios.', '<div>O endpoint da crons de Criterios está montando uma query com vários IDs, passando diversos parâmetros e ocasionando o problema. </div><div><br> </div><div><ul><li>Fazer queries nativas e otimizadas. </li> </ul> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/e2e843de-2691-4d07-914d-086edb4e96fc?fileName=image.png" alt=Image> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/467ce216-70b5-46d6-bcb1-72266e2fc446?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13648', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.295', '2026-03-05 22:46:27', 494, null),
        (576, 'Correções SONAR  - SME 1010 - Perfis e Permissões.', '<div>Correção do Sonar na demanda de Perfis e Permissões. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13650', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END; RETRABALHO', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.296', '2026-03-05 22:46:27', 494, null),
        (577, 'Usuário SESI - Acessando uma empresa e indo até em contrato terceiro em visualizar, está muito ampliado e com barra de rolagem horizontal sem necessidade', '<div>Usuário SESI - Acessando uma empresa e indo até em contrato terceiro em visualizar, está muito ampliado e com barra de rolagem horizontal sem necessidade.<a href="https://drive.google.com/file/d/10dq2wYLJrH5wQFK-3S3pgyJFyuhuMXVc/view?usp=drive_link"><br><br>https://drive.google.com/file/d/10dq2wYLJrH5wQFK-3S3pgyJFyuhuMXVc/view?usp=drive_link</a><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13691', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.296', '2026-03-05 22:46:27', 494, null),
        (578, 'Ao acessar uma empresa/terceiro e indo até cadastrar trabalhador o layout está quebrado.', '<div>Ao acessar uma empresa/terceiro e indo até cadastrar trabalhador o layout está quebrado.<br><br><a href="https://drive.google.com/file/d/133ovVpub8AO-ZRPX3klG8K6Z3vLra9od/view?usp=drive_link"><br>https://drive.google.com/file/d/133ovVpub8AO-ZRPX3klG8K6Z3vLra9od/view?usp=drive_link</a><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13692', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.297', '2026-03-05 22:46:27', 494, null),
        (579, 'Ao estar logado com qualquer usuário SESI e acessando uma empresa ou terceiro e cadastrando uma máquina/equipamento não está aparecendo o modal de que foi cadastrado com sucesso.', '<div>Ao estar logado com qualquer usuário SESI e empresa e acessando uma empresa ou terceiro e cadastrando uma máquina/equipamento não está aparecendo o modal de que foi cadastrado com sucesso. Nem dentro de mobilizações.&nbsp; <a href="https://drive.google.com/file/d/1dUDMfvsouz7ZK77GWSxx1MtGjo6jrbNN/view?usp=drive_link">https://drive.google.com/file/d/1dUDMfvsouz7ZK77GWSxx1MtGjo6jrbNN/view?usp=drive_link</a><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13693', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.297', '2026-03-05 22:46:27', 494, null),
