        (581, 'Não está inativando um formulário (usuário admin empresa), tentando inativar formulário modelo empresa. Após informar a data e justificativa é salvo com sucesso, porém o formulário segue ativo.', '<div>Não está inativando um formulário (usuário admin empresa), tentando inativar formulário modelo empresa. Após informar a data e justificativa é salvo com sucesso, porém o formulário segue ativo.<br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13695', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 20, 3, '2026-03-05 22:46:18.298', '2026-03-05 22:46:27', 494, null),
        (582, 'Remover integração com o Nukleo do campo Tipo do cliente.', '<div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">Remover integração com o Nukleo do campo Tipo do cliente.</span><br style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);"><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">Motivo é que o Nukleo está trazendo dados incorretos.</span><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13697', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.298', '2026-03-05 22:46:27', 494, null),
        (583, 'IDs repetidos em query de Filtro de Usuário', '<div>Durante o Debug, foi notado que algumas queries listam muito ID repetido desnecessariamente, como é o caso da classe QueryFilterDepartmentByUser.&nbsp;<br> </div><div><br> </div><div>Como melhoria, seria necessário um groupBy ou distinct nestas queries. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13712', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.299', '2026-03-05 22:46:27', 494, null),
        (584, 'Remover mensagem "Agradecemos... desempenho"na tela do Logs de Auditoria', '<div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/3c03b816-b18f-469f-ab9f-ef04403c62d2?fileName=image.png" alt=Image> </div><div><br> </div><div>Remover mensagem &quot;Agradecemos... desempenho&quot;na tela do Logs de Auditoria<br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13765', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.300', '2026-03-05 22:46:27', 596, null),
        (585, 'Realizar ordenação dos campos das entidades monitoradas em Logs de Auditoria', '<div>Realizar ordenação em ordem alfabética. </div><div><ul><li>Ajustar protótipo e imagem na SME </li> </ul><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/9eb76bf9-06b1-475b-82f5-20e471de52ff?fileName=image.png" alt=Image><br> </div> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13767', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.300', '2026-03-05 22:46:27', 596, null),
        (586, 'Ajustar SME 0016, detalhar as funcionalidades da versão que gerou dúvidas ao homologador.', '<div><b style="font-weight:normal;"><span style="font-size:11pt;font-family:Arial,sans-serif;color:#000000;background-color:#ffff00;font-weight:400;">SME não fala das funcionalidades restantes “versão”, acredito que seja outra SME (Pendência de avaliação):</span></b><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '13772', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.301', '2026-03-05 22:46:27', 596, null),
