        (654, 'ao adicionar um logo está com acesso negado', '<div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/81d13765-098d-4427-a8f1-a622ab795253?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14579', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'BACKEND', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 20, 3, '2026-03-05 22:46:18.908', '2026-03-05 22:46:27', 628, null),
        (655, '(Melhoria) - Melhoria: colocar um tootlip para ver o nome todo do CNAE quando passar o mouse no cadastro de condições: https://seif.tre2.sesi.org.br/sesi-view/system/criterion/register em caso de nomes de CNAEs extensos, exemplo:', '<div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">Melhoria: colocar um tootlip para ver o nome todo do CNAE quando passar o mouse no cadastro de condições:<span>&nbsp;</span></span><a target=_blank href="https://seif.tre2.sesi.org.br/sesi-view/system/criterion/register" rel="noopener noreferrer" style="font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);">https://seif.tre2.sesi.org.br/sesi-view/system/criterion/register</a><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;"><span>&nbsp;</span>em caso de nomes de CNAEs extensos, exemplo:</span><br> </div><div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;"><br></span> </div><div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;"><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/7a8e97da-ef44-491d-a088-f0c1edc3e4d1?fileName=image.png" alt=Image><br></span> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14580', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', 'FRONT-END; RETRABALHO', null, 'Ta