        (671, '[Sugestão de melhoria] na desmobilização: Na desmobilização mostrar em algum local o motivo e a data da desmobilização.', '<div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">Sugestão de melhoria: Na desmobilização mostrar em algum local o motivo e a data da desmobilização.</span><br style="animation-iteration-count:1 !important;color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);"><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;background-color:rgb(248, 248, 248);display:inline !important;">Exemplo quando desmobilizamos um trabalhado por tipo de motivo outros que inserimos uma justificativa, não tem nenhum local do sistema que mostra esse motivo da desmobilização</span><br> </div>', null, null, 'cancelled', 'high', 'task', 'azure_devops', '14609', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', 'BACKEND; FRONT-END', null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 24, 3, '2026-03-05 22:46:18.912', '2026-03-05 22:46:27', 666, null),
        (672, 'Sugestão de melhoria: mostrar em algum local da empresa cliente os trabalhadores terceiro que estão trabalhando e mobilizados na empresa. Hoje a empresa não consegue identificar os trabalhadores terceiro pela sua visão.', '<div><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;display:inline !important;">Sugestão de melhoria: mostrar em algum local da empresa cliente os trabalhadores terceiro que estão trabalhando e mobilizados na empresa.</span><br style="animation-iteration-count:1 !important;color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;"><span style="color:rgb(29, 28, 29);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;text-align:left;display:inline !important;">Hoje a empresa não consegue indentificar os trabalhadores terceiro pela sua visão.</span><br> </div>', null, null, 'in_progress', 'high', 'task', 'azure_devops', '14610', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF', 'BACKEND; FRONT-END', null, 'Task', null, null, 32, 3, '2026-03-05 22:46:18.913', '2026-03-05 22:46:27', 666, null),
        (673, 'Verificar comportamento do filtro de datas', '<div>O filtro não está funcionando corretamente:&nbsp; </div><div><br> </div><div>Pode ser preciso validar com a análise se esse filtro deve buscar pela data exata ou se a busca é a partir da data. </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/b6e06808-22f9-45c0-9e21-7cae3866d283?fileName=image.png" alt=Image> </div>', null, null, 'cancelled', 'high', 'task', 'azure_devops', '14616', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 003.2025', 'BACKEND; FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 22, 3, '2026-03-05 22:46:18.914', '2026-03-05 22:46:27', 494, null),
        (674, 'Apoio na correção de itens do projeto', null, null, null, 'completed', 'high', 'feature', 'azure_devops', '14696', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 003.2025', null, null, 'User Story', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 22, 3, '2026-03-05 22:46:18.915', '2026-03-05 22:46:18.915', null, null),
        (675, 'Apoio aos itens apontados em treinamento e melhorias (Ju)', null, null, null, 'completed', 'high', 'task', 'azure_devops', '14697', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', null, null, 'Task', 'JULIANA SILVA PACIFICO', 'juliana.pacifico@sc.senai.br', 23, 3, '2026-03-05 22:46:18.915', '2026-03-05 22:46:27', 674, null),
        (676, 'Na visão terceiro, dentro da mobilização não está mostrando a opção de cadastrar um trabalhador subcontratado', '<div>Na visão terceiro, dentro da mobilização não está mostrando a opção de cadastrar um trabalhador subcontratado<br> </div><div> </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/d4b81e0c-96c1-4cea-8ebf-9c6169789918?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14702', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', 'BACKEND; FRONT-END', null, 'Task', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 23, 3, '2026-03-05 22:46:18.915', '2026-03-05 22:46:27', 494, null),
        (677, 'Não permitir o vínculo de um trabalhador subcontratado quando o contrato terceiro x subcontratado estiver inativo', '<div><a href="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/2d492194-d9bb-4503-b4f2-32042ace1206?fileName=bloquear%20vinculo%20subcontratado.mp4&amp;download=true" tabindex=0 style="box-sizing:border-box;color:rgb(0, 90, 158);border-radius:2px;cursor:pointer;outline:transparent;text-decoration:underline;transition:color 80ms cubic-bezier(0.165, 0.84, 0.44, 1), background 80ms linear;">bloquear vinculo subcontratado.mp4</a><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14703', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', 'BACKEND; FRONT-END', null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 23, 3, '2026-03-05 22:46:18.916', '2026-03-05 22:46:27', 494, null),
        (678, 'Ajuste layout modal cadastro trabalhadores', '<div>Nas modais de cadastro de trabalhadores, ao inserir uma opção com o texto grande está quebrando o layout: </div><div><br> </div><div><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/ec6f1fe9-58db-4ef0-9ecd-9b50ce6048d8?fileName=image.png" alt=Image><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14741', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 23, 3, '2026-03-05 22:46:18.917', '2026-03-05 22:46:27', 494, null),
        (679, 'Validação de comportamentos na mobilização, trabalhadores, veículos, máquinas e equipamentos', '<p><strong>1 - Vínculo profissional / trabalhador ativo</strong> </p><ul><li>O trabalhador deve ser inativado ao não ter mais nenhum vínculo profissional ativo </li><li>Fazer inativação via cron </li><li>O status do trabalhador na empresa deve ser replicado nos contratos em que ele está inserido. Fazer via cron. </li><li>O status do trabalhador na mobilização deve refletir o que está no contrato e vice-versa </li><li>Quando o trabalhador estiver com o vinculo profissional vencido (seja via cron ou manualmente), o mesmo deve ser desmobilizado de todas as mobilizações e deve ser validado e informado caso o usuário tente ativar novamente sem um vínculo válido. </li><li>Quando desmobilizar o trabalhador (via cron ou manualmente) o usuário deve ser notificado. </li><li>O trabalhador precisa ter pelo menos um vínculo profissional ativo </li> </ul><p><strong>2 - Trabalhador já mobilizado / trabalhador com vínculo inativo</strong> </p><ul><li>Se o trabalhador estiver como inativo, o mesmo não deve aparecer na busca de trabalhadores para vincular ao contrato da empresa x terceiro, e também não ser mostrado na listagem de trabalhadores na mobilização. </li><li>A listagem de trabalhadores para vincular na mobilização e a listagem para vincular no contrato terceiro x empresa deve trazer o status do trabalhador e o status do vínculo profissional, e permitir a seleção somente dos que estiverem ativos nas duas opções. </li><li>Quando inativar um contrato subcontratado deve inativar todos os vínculos trabalhistas referente a esse subcontratado. </li> </ul><p><strong>3 - Verificar esses comportamentos de ativar e inativar também para veículos, máquinas e equipamentos</strong> </p><p><strong>4 - Precisa verificar o comportamento para quando selecionar ou tirar a seleção na opção todos da mobilização, qual mensagem deve ser mostrada, quando um dos recursos não puder ser vinculado (para todos os tipos de recurso):</strong> </p><p><strong>5 - Inconsistências foi identificado durante testes com múltiplas pessoas utilizando a mesma mobilização:</strong> </p><div style="margin-top:14px;margin-bottom:14px;"> </div><ul><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;">Quando inativado um vinculado profissional no contrato está desmobilização o trabalhador, mas bloqueando o acesso a tela de envio de documentos, mas ao mesmo tempo continua com o informativo de como se tivesse com documento pendente (Pontinho amarelo). (4 horas)</span><br></strong> </li><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(34, 37, 41);display:inline !important;">Mesmo após a desmobilização, o trabalhador continua aparecendo na listagem de referência de atividades. Isso permite que atividades ainda sejam marcadas para ele, mesmo em estado de desmobilizado.<br></span>Esse comportamento incorreto acarreta dois problemas:<br></span></strong> </li><ul><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;">Documentos continuam sendo adicionados ao trabalhador desmobilizado.<br></span></strong> </li><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;">Ao remobilizá-lo, os documentos das atividades atribuídas nesse estado não são recompilados, gerando inconsistência nos dados.<br></span></strong> </li> </ul><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(26, 29, 33);display:inline !important;">Quando há mais de um usuario realizando ações na mobilização faz com que dados apresentados em tela estejam com informações desatualizadas, causando problemas, como:</span><br></span></span></strong> </li><ul><li><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(26, 29, 33);display:inline !important;"><span style="box-sizing:border-box;font-size:14px;"><span style="box-sizing:border-box;color:rgb(209, 210, 211);background-color:rgb(34, 37, 41);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;display:inline !important;"><span style="box-sizing:border-box;background-color:rgb(34, 37, 41);display:inline !important;"><span style="box-sizing:border-box;background-color:rgb(26, 29, 33);display:inline !important;"><span style="box-sizing:border-box;background-color:rgb(34, 37, 41);display:inline !important;">Quando um usuario desmobiliza o trabalhador enquanto o outro está entrando na tela de validação dos documentos ocorre um erro ao não encontrar o valor real atual.</span></span></span></span></span></span></span></span> </li><ul><li>Será necessário atualizar em tempo real ou criar código para garantir que não vai quebrar. </li> </ul> </ul><li><strong><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;font-size:15px;font-weight:400;background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(34, 37, 41);display:inline !important;"><span style="background-color:rgb(26, 29, 33);display:inline !important;"><span style="color:rgb(209, 210, 211);font-family:Slack-Lato, Slack-Fractions, appleLogo, sans-serif;background-color:rgb(34, 37, 41);display:inline !important;">Em maquinas e equipamentos o front-end está deixando o botão apenas cinza, ao invés de não ser possivel pressionar.&nbsp;</span></span></span></span></strong> </li><li>Reduzir a quantidade de compilações que a mobilização executa, para custar menos processamento e causar menos problemas. </li> </ul><strong></strong><p> </p><p> </p><p><strong><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1d094768-adc6-4d4d-8e1e-8ede1aba669b?fileName=image.png" alt=Image><br></strong> </p><br>', null, null, 'completed', 'high', 'task', 'azure_devops', '14751', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', 'BACKEND; FRONT-END', null, 'Task', 'FABRISIO PEREIRA BEZ FONTANA FILHO', 'fabrisio.filho@sc.senai.br', 23, 3, '2026-03-05 22:46:18.917', '2026-03-05 22:46:27', 494, null),
        (680, 'Migração de Repositório SEIF - Gestão de Terceiros e Alinhamentos com a equipe.', null, null, null, 'completed', 'high', 'task', 'azure_devops', '14778', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'LUCAS VIANA RODRIGUES', 'lucas.rodrigues@sc.senai.br', 20, 3, '2026-03-05 22:46:18.918', '2026-03-05 22:46:27', 494, null),
        (681, 'Tech Lead - Mobilização e Desmobilização', null, null, null, 'completed', 'high', 'task', 'azure_devops', '14779', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4', null, null, 'Task', 'JOAO LUCCAS DAMIANI', 'joao.damiani@sc.senai.br', 24, 3, '2026-03-05 22:46:18.918', '2026-03-05 22:46:27', 545, null),
        (682, 'Apontamento de Horas [DEV]', null, null, null, 'completed', 'high', 'task', 'azure_devops', '14799', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 001.2025', null, null, 'Task', 'VINICIUS GABRIEL MARTINS DA SILVA', 'vinicius.gabriel@sc.senai.br', 20, 3, '2026-03-05 22:46:18.918', '2026-03-05 22:46:27', 545, null),
        (683, 'Correção na aba dados profissionais de trabalhadores, ajustar layout quebrand.', '<div>Correção na aba dados profissionais de trabalhadores, ajustar layout quebrando e validar o Status que não está persistindo.<br> </div><div> </div><div><br>Logado como DN, e acessando a visão do terceiro/empresa, indo até trabalhadores, e em dados profissionais, ao editar o layout está quebrando.<br><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/86ec9861-fc51-4860-8cf2-21ea4f84eebe?fileName=image.png" alt=Image style="width:604px;" width=604 height=272><br><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/c512d322-a7ce-4f6a-a3d0-444ac9f3b9c1?fileName=image.png" alt=Image><br><br> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14811', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', 'FRONT-END', null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 23, 3, '2026-03-05 22:46:18.920', '2026-03-05 22:46:27', 494, null),
        (684, 'Contrato Terceiro x Empresas Aprovados precisam ter a edição habilitadas.', '<div>Contrato Terceiro x Empresas Aprovados precisam ter a edição habilitadas.<br> </div><div><br>Visões Empresa e Terceiro.<br><br>Caso seja na visão empresa, qualquer edição irá aprovar automaticamente. </div><div><br>Caso seja na visão terceiro, qualquer edição irá ter que aguardar a aprovação da empresa.<br><br>Vídeo para entendimento:&nbsp;<div><div><a href="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1cf19096-4e86-4248-adf9-2a0edc02f533?fileName=ContratoTerceiroXEmpresaAprovadosSemEdicao.mp4&amp;download=true" tabindex=0>ContratoTerceiroXEmpresaAprovadosSemEdicao.mp4</a> </div> </div><br><br>Qualquer dúvida contatar a <a href="#" data-vss-mention="version:2.0,f6ccbafb-f0f8-626a-afad-bd123a939b72">@JULIANA SILVA PACIFICO</a> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14829', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', null, null, 'Task', 'JULIO CESAR BONZANINO PEREIRA', 'julio.bonzanino@sc.senai.br', 23, 3, '2026-03-05 22:46:18.920', '2026-03-05 22:46:27', 494, null),
        (685, 'Impedir a exclusão de um formulário do critério de mobilização caso já tenha sido utilizado em uma mobilização (Testar se ao inativar o formulário o erro também acontece).)', '<div><br> </div><div>Impedir a exclusão de um formulário do critério de mobilização caso já tenha sido utilizado em uma mobilização (Testar se ao inativar o formulário o erro também acontece).)<br><br><br>Extraído de: <a href="https://docs.google.com/document/d/1gLggLWdPDWPyDMRPocUCqKxmtFfqrrm05LSdGSUoZqM/edit?tab=t.0">https://docs.google.com/document/d/1gLggLWdPDWPyDMRPocUCqKxmtFfqrrm05LSdGSUoZqM/edit?tab=t.0</a> </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '14840', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Gestão de Terceiros\Sprint 004.225', null, null, 'Task', 'RENAN ZAPELINI DO NASCIMENTO', 'renan.nascimento@sc.senai.br', 23, 3, '2026-03-05 22:46:18.920', '2026-03-05 22:46:27', 494, null),
