        (793, 'Conversão da Matriz para Mobilização', '<div><b style="font-weight:normal;"><span style="font-size:11pt;font-family:&quot;Arial Narrow&quot;, sans-serif;color:rgb(255, 255, 255);font-weight:400;">Realizar a migração dos documentos da “Matriz de Documentos” do Chamada Tecnológica para o módulo “Mobilização” de Gestão de Terceiros, por meio de um processo automatizado de conversão de dados, assegurando a integridade e compatibilidade das informações entre os sistemas.</span></b><br> </div><div><b style="font-weight:normal;"><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;"><br></span></b> </div><div><b style="font-weight:normal;"><span style="font-size:11pt;font-family:&quot;Arial Narrow&quot;, sans-serif;color:rgb(255, 255, 255);font-weight:400;">card no trello:</span><span style="font-size:11pt;font-family:''Arial Narrow'',sans-serif;color:#000000;font-weight:400;">&nbsp;<a href="https://trello.com/c/eLrnqaTX">https://trello.com/c/eLrnqaTX</a></span></b> </div>', null, null, 'pending', 'high', 'task', 'azure_devops', '26987', 'Tribo SEIF\Projetos\Chamada Tecnológica', 'Tribo SEIF\Sprints SEIF Nacional 2024\Sprint 24', null, null, 'Task', null, null, 17, 2, '2026-03-05 22:46:19.565', '2026-03-05 22:46:27', 786, null),
