        (1001, 'Dev - Inconsistência no Link de Confirmação de Usuário – Ambiente de Treinamento', '<div>Trocar a variavel de ambiente do backend para a URL nova. </div>', null, null, 'completed', 'high', 'task', 'azure_devops', '28626', 'Tribo SEIF\Sustentação\Gestão de Terceiros', 'Tribo SEIF', null, null, 'Task', 'JONATHAN NEVES', 'jonathan.neves@sc.senai.br', 32, 3, '2026-03-05 22:46:21.181', '2026-03-05 22:46:27', 1050, null),
        (1002, 'Erro cadastro usuário admin empresa', '<div>Explicação do problema:&nbsp;<a href="https://drive.google.com/file/d/1_5AiZI6yGRMB71Z9PUM0kbLQAoTT95kg/view?usp=sharing">https://drive.google.com/file/d/1_5AiZI6yGRMB71Z9PUM0kbLQAoTT95kg/view?usp=sharing</a> </div><div><br> </div>', null, null, 'completed', 'low', 'task', 'azure_devops', '28664', 'Tribo SEIF\Sustentação\Gestão de Terceiros', 'Tribo SEIF', null, null, 'Ticket', 'BRUNO PAES DE MEDEIROS', 'bruno.paes@sc.senai.br', 32, 3, '2026-03-05 22:46:21.183', '2026-03-05 22:46:21.183', null, null),
