        (1592, '[DEV BACK] SME 0127 Incluir a função de: Edição de Contrato de Terceiro e Empresa Cliente', null, null, null, 'completed', 'high', 'task', 'azure_devops', '34170', 'Tribo SEIF\Projetos\Gestão de Terceiros', 'Tribo SEIF\Sprints SEIF Fase 4\Sprint-07', null, null, 'Task', 'LUCAS FRISON GONCALVES', 'lucas.frison@sc.senai.br', 31, 3, '2026-03-05 22:46:25.002', '2026-03-05 22:46:29', 1175, null),
        (1593, 'Bug em desmobilizações anteriores a SME 109 (Critérios de desmobilização)', '<div><span style="display:inline !important;">1 - Há um bug na parte de desmobilização, quando entro em uma mobilização desmobilizada antiga, não está validando se os recursos e seus documentos estão desmobilizados, ocorrendo casos como esse (ele só atualiza o status quando entra na pasta de documentos do recurso)</span><br> </div><div><span style="display:inline !important;"><br></span> </div><div><span style="display:inline !important;"><img src="https://dev.azure.com/senaisc-solucoes-digitais/c8f81c43-58a6-4ce1-96ce-4771ae6a012d/_apis/wit/attachments/1b959951-4c39-459a-bee7-9c8d331b37df?fileName=image.png" alt=Image style="box-sizing:border-box;max-width:100%;align-self:center;"><br></span> </div><div> </div>', null, null, 'completed', 'low', 'task', 'azure_devops', '34176', 'Tribo SEIF\Sustentação\Gestão de Terceiros', 'Tribo SEIF', null, null, 'Ticket', null, null, 32, 3, '2026-03-05 22:46:25.003', '2026-03-05 22:46:25.003', null, null),
